function deleteEveryNth(arr0, n, dim = 0) {
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error('n must be a positive integer');
  }

  // Use tidy so temporary tensors are freed promptly
  return tf.tidy(() => {
    const t = tf.tensor(arr0);
    const rank = t.rank;

    let axis = dim;
    if (!Number.isInteger(axis)) {
      throw new Error('dim must be an integer');
    }
    if (axis < 0) axis = rank + axis;
    if (axis < 0 || axis >= rank) {
      throw new Error(`dim out of range (got ${dim}, tensor rank ${rank})`);
    }

    const size = t.shape[axis];
    if (size === 0) return t.arraySync(); // nothing to do
    if (n > size) return t.arraySync();   // nothing to remove

    // Build indices to keep: keep indices i where (i+1) % n !== 0
    const keep = [];
    for (let i = 0; i < size; i++) {
      if ((i + 1) % n !== 0) keep.push(i);
    }

    // If nothing removed, return original as array
    if (keep.length === size) return t.arraySync();

    const keepIdx = tf.tensor1d(keep, 'int32');
    const result = tf.gather(t, keepIdx, axis);
    // return plain nested JS array
    return result.arraySync();
  });
