  const flat = new Float32Array(rows * cols);
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      const v = Number(input[i][j]);
      flat[i * cols + j] = Number.isFinite(v) ? v : 0;
    }
