export function earliestLatestDates(df0, options = {}) {
  const {
    columnName = 'Date',
    timezone = 'UTC',
    extraFormats = [ 'M/d/yyyy', 'M/d/yy', 'MM/dd/yyyy', 'dd/MM/yyyy', 'dd-MMM-yyyy', 'MMM d, yyyy', 'yyyyMMdd' ]
  } = options;

  if (!df0) return null;

  // Extract column values
  let values = [];
  if (Array.isArray(df0)) {
    // array of rows (objects)
    values = df0.map(r => (r && Object.prototype.hasOwnProperty.call(r, columnName)) ? r[columnName] : undefined);
  } else if (Array.isArray(df0[columnName])) {
    // object with column arrays: { Date: [...] }
    values = df0[columnName];
  } else {
    // unknown shape
    // try to treat df0 as an iterable of rows
    try {
      for (const row of df0) {
        values.push(row && row[columnName]);
      }
    } catch (e) {
      // fallback: not iterable
      return null;
    }
  }

  // Helper: attempt to parse a single value into Luxon DateTime (or null)
  const parseValue = (v) => {
    if (v == null || v === '') return null;

    // If it's already a Date object
    if (v instanceof Date && !isNaN(v)) {
      return DateTime.fromJSDate(v, { zone: timezone });
    }

    // If it's a number, assume epoch millis
    if (typeof v === 'number' && Number.isFinite(v)) {
      // If it looks like seconds (10-digit), convert to ms
      const maybeMillis = (String(Math.abs(v)).length <= 10) ? v * 1000 : v;
      return DateTime.fromMillis(maybeMillis, { zone: timezone });
    }

    // If it's a string, try multiple parse strategies
    if (typeof v === 'string') {
      const s = v.trim();
      if (s === '') return null;

      // Try ISO
      let dt = DateTime.fromISO(s, { zone: timezone });
      if (dt.isValid) return dt;

      // Try RFC2822 (e.g., "Mon, 25 Dec 1995 13:30:00 GMT")
      dt = DateTime.fromRFC2822(s, { zone: timezone });
      if (dt.isValid) return dt;

      // Try SQL
      dt = DateTime.fromSQL(s, { zone: timezone });
      if (dt.isValid) return dt;

      // Try common extra formats
      for (const fmt of extraFormats) {
        dt = DateTime.fromFormat(s, fmt, { zone: timezone });
        if (dt.isValid) return dt;
      }

      // Last resort: let JS Date parse then wrap (less reliable)
      const jsd = new Date(s);
      if (!isNaN(jsd)) return DateTime.fromJSDate(jsd, { zone: timezone });
    }

    return null;
  };

