  const parsed = values
    .map((raw) => ({ raw, dt: parseValue(raw) }))
    .filter(x => x.dt && x.dt.isValid);

  if (parsed.length === 0) return null;

  // Find min and max by epoch milliseconds
  let min = parsed[0];
  let max = parsed[0];
  for (const p of parsed) {
    const ms = p.dt.toMillis();
    if (ms < min.dt.toMillis()) min = p;
    if (ms > max.dt.toMillis()) max = p;
