 * @param {string} idField - The property name containing the identifier (default: 'id')
 * @returns {Array<Object>} New array with items reordered according to sequence
 */
function reorderBySequence(items, sequence, idField = 'id') {
  // Create a Map for O(1) lookup of sequence positions
  const sequenceMap = new Map(sequence.map((id, index) => [id, index]));

  // Sort items based on their position in the sequence
  return items.sort((a, b) => {
    const indexA = sequenceMap.get(a[idField]);
    const indexB = sequenceMap.get(b[idField]);

    // Items in sequence come first, sorted by sequence order
    // Items not in sequence come last, maintaining relative order
    if (indexA !== undefined && indexB !== undefined) {
      return indexA - indexB;
