function convertToBinaryColumns(df0) {
    // Import the necessary library (Danfo.js, a JavaScript port of Pandas)
    const dfd = require('danfojs');

    // Initialize an empty DataFrame to store the transformed data
    let transformedDf = new dfd.DataFrame();

