    rows = df0.objects();
    wasArquero = true;
  } else if (Array.isArray(df0)) {
    rows = df0.map((r) => ({ ...r })); // copy to avoid mutating caller's objects
  } else {
    throw new Error('df0 must be an Arquero table or an array of objects');
  }

  if (rows.length === 0) {
    // nothing to do
    return returnArquero ? aq.table([]) : [];
  }

  // Determine columns available
  const allCols = Object.keys(rows[0]);

  // Auto-detect categorical columns if user didn't supply explicit list
  const pickColumns = new Set();
