      if (!allCols.includes(c)) {
        throw new Error(`Column "${c}" not found in data`);
      }
      pickColumns.add(c);
    }
  } else {
    // Auto-detection rules:
    // - any column that has at least one string or boolean value -> categorical
    // - numeric columns with distinct count <= maxCategories -> categorical
    for (const col of allCols) {
      const vals = [];
      for (let i = 0; i < rows.length; i++) {
        const v = rows[i][col];
        // treat undefined as null/NA but still include to help detection if all values undefined then skip
        vals.push(v === undefined ? null : v);
