      const hasString = nonNull.some((v) => typeof v === 'string');
      const hasBoolean = nonNull.some((v) => typeof v === 'boolean');
      const hasNumber = nonNull.some((v) => typeof v === 'number' && !Number.isNaN(v));
      if (hasString || hasBoolean) {
        pickColumns.add(col);
        continue;
      }
      if (hasNumber && !hasString && !hasBoolean) {
        // numeric column: check distinct count
        const uniq = new Set(nonNull);
        if (uniq.size <= maxCategories) {
          pickColumns.add(col);
        }
        continue;
      }
      // otherwise ignore (e.g., objects or mixed types)
    }
  }

  // If nothing to encode, return original (copied) rows
  if (pickColumns.size === 0) {
    return returnArquero ? aq.table(rows) : rows;
  }

  // Helper to sanitize category strings for column names
  const sanitize = (s) => {
    if (s === null) return 'null';
    if (s === undefined) return 'undefined';
    // convert to string and replace whitespace and unsafe chars with _
    return String(s).replace(/[^0-9A-Za-z_]/g, '_').replace(/^_+|_+$/g, '') || 'val';
  };

  // For each categorical column, compute unique categories (and maintain insertion order)
  const colToCategories = new Map();
  for (const col of Array.from(pickColumns)) {
    const seen = new Map(); // preserve order
    for (const r of rows) {
      const v = (r[col] === undefined ? null : r[col]);
      if (!seen.has(v)) seen.set(v, true);
    }
    const categories = Array.from(seen.keys());
    // Optionally dropFirst: we will skip the first category later when creating dummies
    colToCategories.set(col, categories);
  }

  // Create new rows with added one-hot columns
  const newRows = rows.map((r) => ({ ...r })); // shallow copy each row
  for (const [col, categories] of colToCategories.entries()) {
    // determine which categories to create columns for
    const catsToMake = dropFirst ? categories.slice(1) : categories.slice();
    for (const cat of catsToMake) {
      const colName = `${col}_${sanitize(cat)}`;
      // avoid name collision: if already exists, append suffix until unique
      let finalName = colName;
      let k = 1;
      while (Object.prototype.hasOwnProperty.call(newRows[0], finalName)) {
        finalName = `${colName}_${k}`;
        k += 1;
      }
