      for (let i = 0; i < newRows.length; i++) {
        const val = newRows[i][col] === undefined ? null : newRows[i][col];
        // treat NaN specially: JS number NaN !== NaN so use Object.is
        const equal = Object.is(val, cat) || (val === cat);
        newRows[i][finalName] = equal ? 1 : 0;
      }
    }
  }

  // Drop original categorical columns unless requested to keep
  if (!keepOriginals) {
    for (const col of pickColumns) {
      for (const r of newRows) {
