/**
 * Adds a new column 'col0' to a tabular dataset df0 based on a condition.
 * @param {Object} df0 - The input dataset (must be DuckDB-compatible).
 * @param {string} colA - The name of the column to compare against.
 * @param {number} val0 - The threshold value for comparison.
 * @param {string} labelHigh - The label for values > val0.
 * @param {string} labelLow - The label for values <= val0.
 * @returns {Promise<Object>} - The updated dataset with the new column.
 */
async function addConditionalColumn(df0, colA, val0, labelHigh = 'label_high', labelLow = 'label_low') {
    // Initialize DuckDB.js
    const duckdb = await import('https://cdn.jsdelivr.net/npm/duckdb@latest/dist/duckdb.mjs');

    // Convert the input data to a format DuckDB can process
    const data = Object.values(df0).map(row => Object.values(row));

    // Create a temporary table in DuckDB
    const conn = await duckdb.connect();
    await conn.execute(`
        CREATE TABLE temp_data AS SELECT * FROM values(${data});
    `);

    // Get column names from the first row
    const columnNames = Object.keys(df0[0]);

    // Construct the query to add the new column
    const query = `
        SELECT *,
               CASE WHEN ${colA} > ${val0} THEN '${labelHigh}' ELSE '${labelLow}' END AS col0
        FROM temp_data
    `;

    // Execute the query and fetch results
    const result = await conn.execute(query);
    const updatedData = result.toArray();

    // Convert back to the original format (assuming df0 was an array of objects)
    const updatedDf = updatedData.map(row => {
        const obj = {};
        columnNames.forEach((name, i) => {
            obj[name] = row[i];
        });
        return obj;
    });

    // Clean up
    await conn.execute('DROP TABLE temp_data');
    await conn.close();

    return updatedDf;
}

