 *
 * @param {number[] | import('@tensorflow/tfjs').Tensor} input - 1-D input vector (JS array or tf.Tensor1D).
 * @param {number} times - Number of clones (positive integer).
 * @param {number} [axis=0] - Axis to clone along: 0 => produce shape [times, n], 1 => produce shape [n, times].
 * @param {Object} [options] - Optional settings.
 * @param {boolean} [options.returnTensor=false] - If true, return a tf.Tensor2D; otherwise return a plain JS array.
 * @param {Object} [options.tfLib=tf] - (Optional) Provide the tf library instance (useful in some bundlers).
 * @returns {Array|import('@tensorflow/tfjs').Tensor2D} The cloned matrix as a nested JS array or a tf.Tensor2D.
 *
 * Example:
 *   cloneVector([1,2,3], 4, 0) // -> [[1,2,3],[1,2,3],[1,2,3],[1,2,3]]
 *   cloneVector([1,2,3], 2, 1) // -> [[1,1],[2,2],[3,3]]
 */
function cloneVector(input, times, axis = 0, options = {}) {
  const tfLib = options.tfLib || (typeof tf !== 'undefined' ? tf : null);
  if (!tfLib) {
    throw new Error('TensorFlow.js (tf) not found. In Node: npm install @tensorflow/tfjs and require it. In browser: include the tfjs CDN.');
  }

  if (!Number.isInteger(times) || times < 1) {
    throw new TypeError('times must be a positive integer');
  }
  if (axis !== 0 && axis !== 1) {
    throw new TypeError('axis must be 0 or 1 for a 1-D input vector');
  }

  // Create a tf.Tensor1D if input is a plain array
  const tensor1d = input instanceof tfLib.Tensor ? input.flatten() : tfLib.tensor1d(input);

  if (tensor1d.shape.length !== 1) {
    throw new TypeError('input must be a 1-D vector');
  }

  const n = tensor1d.shape[0];

  let reshaped;
  if (axis === 0) {
    // treat as row vector [1, n], tile times along axis 0 -> [times, n]
    reshaped = tensor1d.reshape([1, n]).tile([times, 1]);
  } else {
    // axis === 1: treat as column [n, 1], tile times along axis 1 -> [n, times]
    reshaped = tensor1d.reshape([n, 1]).tile([1, times]);
  }

  if (options.returnTensor) {
    return reshaped;
  } else {
