  if (!df0 || !(df0 instanceof dfd.DataFrame)) {
    throw new Error("df0 must be a valid Danfo DataFrame");
  }
  if (!Array.isArray(lst0) || lst0.length === 0) {
    throw new Error("lst0 must be a non-empty array of column names");
