 * @param {*} boundA - one bound of the inclusive range
 * @param {*} boundB - the other bound of the inclusive range
 * @returns {number[]} array of indices whose corresponding values lie within [min(boundA,boundB), max(boundA,boundB)]
 */
export function indicesInRange(seq, boundA, boundB) {
  if (seq == null) return [];

  const arr = Array.from(seq);
  const low = boundA <= boundB ? boundA : boundB;
  const high = boundA <= boundB ? boundB : boundA;

  // build pairs {value, index}, filter by range, then extract indices
  const pairs = map(arr, (value, index) => ({ value, index }));
  const filtered = filter(pairs, p => {
    // exclude NaN (NaN comparisons are always false); allow other JS comparables
    if (typeof p.value === "number" && Number.isNaN(p.value)) return false;
    return p.value >= low && p.value <= high;
