const standardIntegerSchema = z.number().int().gte(-Math.pow(2, 31)).lte(Math.pow(2, 31) - 1);

// Define the schema for a two-item array with the specified types
const twoItemGroupingSchema = z.tuple([wideRangeIntegerSchema, standardIntegerSchema]);

// Function to check if each element in the input collection is a valid two-item grouping
function checkTwoItemGroupings(inputCollection) {
    return inputCollection.map(item => {
        try {
            // Parse the item against the schema
            twoItemGroupingSchema.parse(item);
            return true; // Item is a valid two-item grouping
        } catch (error) {
            return false; // Item is not a valid two-item grouping
        }
    });
}

