console.log(
  checkPairs([
    [123n, 1],                        // true: BigInt and safe integer
    ["999999999999999999999", 0],     // true: big integer expressed as string, and safe integer
    ["-42", 7],                       // true
    [42, 7],                          // false: first component is plain Number (not BigInt/string integer)
    [123n, 1.5],                      // false: second component not integer
    ["12a", 3],                       // false: string not an integer
    [123n, Number.MAX_SAFE_INTEGER+1] // false: second not a safe integer
  ])
);
// => [true, true, true, false, false, false, false]

Notes:
