 * @returns {string[]} - New array containing the subset.
 *
 * Throws descriptive Zod errors for invalid inputs.
 */
export function extractSubset(entries, startIndex, endIndex) {
  // Validate inputs
  const Schema = z.tuple([
    z.array(z.string(), { required_error: "entries must be an array of strings" }),
    z.number().int({ message: "startIndex must be an integer" }),
    z.number().int({ message: "endIndex must be an integer" }),
  ]);

  const [arr, startRaw, endRaw] = Schema.parse([entries, startIndex, endIndex]);

  const len = arr.length;

  // Helper to normalize negative indices: -1 => len - 1, etc.
