// npm install @polars/js
import pl from "@polars/js";

/**
 * updateFromDf
 * Update df0 with values from df1 for rows that match on "keys".
 *
 * Parameters:
 *  - df0Input: Array<Object> | pl.DataFrame    (source dataset to be updated)
 *  - df1Input: Array<Object> | pl.DataFrame    (dataset with new values)
 *  - opts:
 *      - keys: string | string[]   (column name or array of column names to match on)  REQUIRED
 *      - updateCols?: string[]     (which columns to update in df0; default: all non-key columns from df1)
 *
 * Returns: pl.DataFrame (a new DataFrame with the updates applied)
 */
export function updateFromDf(df0Input, df1Input, opts) {
  if (!opts || !opts.keys) throw new Error("opts.keys is required (string or string[]).");

  const keys = Array.isArray(opts.keys) ? opts.keys : [opts.keys];

  // Convert inputs to Polars DataFrame if needed
  const df0 = pl.DataFrame.isDataFrame(df0Input) ? df0Input : pl.DataFrame(df0Input);
  const df1 = pl.DataFrame.isDataFrame(df1Input) ? df1Input : pl.DataFrame(df1Input);

  // Validate keys exist
  for (const k of keys) {
    if (!df0.columns.includes(k)) throw new Error(`Key column "${k}" not found in df0`);
    if (!df1.columns.includes(k)) throw new Error(`Key column "${k}" not found in df1`);
  }

  // Determine columns to update: user-specified or all non-key columns from df1
  const updateCols = opts.updateCols && opts.updateCols.length
    ? opts.updateCols
    : df1.columns.filter(c => !keys.includes(c));

  if (updateCols.length === 0) {
    // nothing to update
    return df0.clone();
  }

  // Check update columns exist in df1
  for (const c of updateCols) {
    if (!df1.columns.includes(c)) throw new Error(`Update column "${c}" not found in df1`);
  }

  // Prepare df1 with renamed update columns to avoid collisions when joining
  const renameMap = {};
  for (const c of updateCols) {
    renameMap[c] = `${c}__new`;
  }
  const df1Renamed = df1.rename(renameMap);

  // Left-join df0 with df1Renamed on keys
  // This will add df1's (renamed) update columns alongside df0 columns for matched rows
  const joined = df0.join(df1Renamed, { on: keys, how: "left" });

  // For each update column, use df1 value where present, otherwise keep df0 value.
  // Expression: coalesce(df1_col_new, df0_col)
  const updateExprs = updateCols.map(c => {
    const newCol = `${c}__new`;
    // pl.col(newCol).fillNull(pl.col(c)).alias(c)   // equivalent behavior
    return pl.col(newCol).isNotNull()
      .then(pl.col(newCol))
      .otherwise(pl.col(c))
      .alias(c);
  });

  // Apply updates and select original columns in original order
  const final = joined.withColumns(updateExprs).select(df0.columns);

  return final;
}

