      }
      startRow = 1; // don't modify headers; modify data rows only
    }

    // Apply transformation to each data row
    for (let r = startRow; r < rows.length; r++) {
      const row = rows[r];
      if (!Array.isArray(row)) continue; // skip invalid rows
      if (colIndex >= 0 && colIndex < row.length) {
        row[colIndex] = toUpperSafe(row[colIndex]);
      }
    }

    return rows;
  }

  // Case: array of objects (rows are objects)
  if (typeof clone[0] === "object" && clone[0] !== null && !Array.isArray(clone[0])) {
