/**
 * Compute element-wise difference of two identically sized 2D tables (df0 - df1).
 * @param {Array<Array<number>>} df0 - first 2D array
 * @param {Array<Array<number>>} df1 - second 2D array (same shape as df0)
 * @returns {Array<Array<number>>} - resulting 2D array of differences
 * @throws {Error} if inputs are not same shape or not proper 2D arrays
 */
function tableDifference(df0, df1) {
  // Basic validation
  if (!Array.isArray(df0) || !Array.isArray(df1)) {
    throw new Error('Both df0 and df1 must be 2D arrays.');
  }
  const rows = df0.length;
  if (rows !== df1.length) {
    throw new Error('df0 and df1 must have the same number of rows.');
  }
  if (rows === 0) return []; // empty table

  const cols = df0[0].length;
  if (!Number.isInteger(cols) || cols < 0) {
    throw new Error('df0 must be a 2D array with consistent row length.');
  }

  for (let r = 0; r < rows; r++) {
    if (!Array.isArray(df0[r]) || !Array.isArray(df1[r])) {
      throw new Error('df0 and df1 must be 2D arrays (arrays of arrays).');
    }
    if (df0[r].length !== cols || df1[r].length !== cols) {
      throw new Error('All rows must have the same number of columns and shapes must match.');
    }
  }

  // Use tf.tidy to automatically dispose intermediate tensors
  const result = tf.tidy(() => {
