 * @param {string} [col2='col2'] - property name for the second column (if rows are objects)
 * @returns {Array} - Array of tuples: [ [valueOfCol1, valueOfCol2], count ]
 */
export function pairFrequencies(table, col1 = 'col1', col2 = 'col2') {
  if (!Array.isArray(table)) {
    throw new TypeError('table must be an array of rows');
  }

  // Normalize each row to a two-item array [v1, v2]
  const normalized = table.map((row, idx) => {
    if (Array.isArray(row)) {
      return [row[0], row[1]];
    }
    if (row && typeof row === 'object') {
      return [row[col1], row[col2]];
    }
    throw new TypeError(`Row at index ${idx} is neither an array nor an object`);
