      // Get column index
      const colIndex = typeof column === 'string' 
        ? headers.indexOf(column)
        : column;

      if (colIndex === -1) throw new Error(`Column not found: ${column}`);

      const cellValue = row[colIndex];

      // Apply operator
      switch (operator) {
        case '==':
          return cellValue == value;
        case '!=':
          return cellValue != value;
        case '>':
          return cellValue > value;
