import { map } from 'remeda';

/**
 * Keep only rows from tableA that have a matching row in tableB.
 *
 * @param {Array<Object>} tableA - Array of objects (rows) to filter.
 * @param {Array<Object>} tableB - Array of objects used to test matches.
 * @param {string | Array<string> | ((row: Object) => string)} key - How to derive the match key:
 *    - string: property name to match on
 *    - Array<string>: multiple property names combined into a composite key
 *    - function: custom function that returns a string key for a row
 * @returns {Array<Object>} - Filtered rows from tableA that have a match in tableB.
 */
export function filterMatchingRows(tableA, tableB, key) {
  if (!Array.isArray(tableA) || !Array.isArray(tableB)) {
    throw new TypeError('tableA and tableB must be arrays');
  }

  const keyFn = typeof key === 'function'
    ? key
    : (row) => {
        if (Array.isArray(key)) {
          // composite key: join values with a separator unlikely to appear in data
          return key.map(k => String(row?.[k])).join('::');
        }
        // single key (string)
        return String(row?.[key]);
      };

  // Build a fast lookup set of keys from tableB using Remeda's map utility
  const keysB = new Set(map(tableB, keyFn));

  // Filter tableA keeping only rows whose key exists in keysB
  return tableA.filter(row => keysB.has(keyFn(row)));
}

