const dfd = require("danfojs-node");

/**
 * Reset the row index of a table and convert the existing index values into new columns.
 *
 * Accepts:
 *  - a dfd.DataFrame
 *  - an array of objects (e.g. [{a:1,b:2}, ...])
 *  - an array of arrays with a columns array supplied in opts.columns
