 *  - returnFormat: "dataframe" | "json" | "array" (default: "json")
 *  - columns: if input is array of arrays, provide column names via opts.columns
 *
 * Returns:
 *  - depending on returnFormat: a dfd.DataFrame, an array of objects, or a 2D array
 */
function resetTableIndex(inputTable, opts = {}) {
  const { indexColName = "index", returnFormat = "json", columns = null } = opts;

  // Normalize to danfo DataFrame
  let df;
  if (inputTable && typeof inputTable === "object" && inputTable instanceof dfd.DataFrame) {
    df = inputTable.copy();
  } else if (Array.isArray(inputTable)) {
    // Could be array of objects or array of arrays
    if (inputTable.length === 0) {
      // empty table -> create empty DataFrame
      df = new dfd.DataFrame([]);
    } else if (Array.isArray(inputTable[0])) {
      // array of arrays; need columns
      if (!columns || !Array.isArray(columns)) {
        throw new Error("When supplying an array-of-arrays, you must provide opts.columns as an array of column names.");
      }
      df = new dfd.DataFrame(inputTable, { columns });
    } else {
      // assume array of objects
      df = new dfd.DataFrame(inputTable);
    }
  } else {
    throw new Error("Unsupported input type. Provide a dfd.DataFrame, array of objects, or array of arrays + opts.columns.");
  }

  // Use danfo's resetIndex to move the existing index into a column
  // danfojs resetIndex signature: df.resetIndex({drop=false, inplace=false})
  // It will create a column named "index" by default. We'll rename afterwards if indexColName differs.
  const newDf = df.resetIndex({ drop: false, inplace: false });

  // If user requested a custom index column name, rename the created column
  if (indexColName !== "index") {
    // only rename if column exists
    if (newDf.columns.includes("index")) {
      newDf.rename({ index: indexColName }, { inplace: true });
    } else {
      // Some inputs might already have index saved under another name (unlikely),
      // so avoid throwing — just proceed.
    }
  }

  // Return in requested format
  if (returnFormat === "dataframe") {
    return newDf;
  } else if (returnFormat === "json") {
    // toJSON returns array of objects
    return newDf.toJSON();
  } else if (returnFormat === "array") {
    // return a 2D array, with header as first row
    const header = newDf.columns.slice();
    const rows = newDf.values;
    return [header, ...rows];
  } else {
    throw new Error("Unsupported returnFormat. Use 'dataframe', 'json', or 'array'.");
  }
}

