/**
 * Convert a labeled tabular dataset `df` into an array of objects where each object:
 *  - contains all column:value pairs for a row
 *  - includes the row's positional index under the key indexName (default: "index")
 *
 * Supports:
 *  - polars.DataFrame (uses df.rows() and df.columns)
 *  - plain Array of objects (Array<{...}>)
 *
 * @param {object|Array} df - The input dataset (polars.DataFrame or array-of-objects).
 * @param {object} [opts] - Options.
 * @param {string} [opts.indexName='index'] - Name of the index key to add to each row object.
 * @returns {Array<object>} - Array of row objects including index.
 */
function dataframeToObjects(df, opts = {}) {
  const indexNameBase = opts.indexName || 'index';

  // Helper: pick an index key that doesn't collide with existing column names
  function chooseIndexKey(existingCols, baseName) {
    if (!Array.isArray(existingCols)) return baseName;
    if (!existingCols.includes(baseName)) return baseName;
    let i = 1;
    while (existingCols.includes(`${baseName}_${i}`)) i++;
    return `${baseName}_${i}`;
  }

