  // polars.DataFrame typically has .rows() method and .columns array
  if (df && typeof df.rows === 'function' && Array.isArray(df.columns)) {
    const cols = df.columns.slice(); // array of column names
    const rows = df.rows(); // returns array-of-arrays, each row an array of cell values
    const indexKey = chooseIndexKey(cols, indexNameBase);
    return rows.map((rowArr, rowIndex) => {
      const obj = { [indexKey]: rowIndex };
      for (let j = 0; j < cols.length; j++) {
        obj[cols[j]] = rowArr[j];
      }
      return obj;
    });
  }

  // Case 2: Plain array-of-objects (common JS representation)
  if (Array.isArray(df) && (df.length === 0 || typeof df[0] === 'object')) {
    const indexKey = chooseIndexKey(
      df.length > 0 ? Object.keys(df[0]) : [],
      indexNameBase
    );
    return df.map((rowObj, i) => {
      // shallow clone to avoid mutating original
      return { [indexKey]: i, ...(rowObj || {}) };
    });
  }

  // Case 3: If object exposes toArray / toRows style methods, try them generically
  if (df && typeof df.toArray === 'function' && Array.isArray(df.columns)) {
    const cols = df.columns.slice();
    const rows = df.toArray();
    const indexKey = chooseIndexKey(cols, indexNameBase);
    return rows.map((rowArr, rowIndex) => {
      const obj = { [indexKey]: rowIndex };
      for (let j = 0; j < cols.length; j++) obj[cols[j]] = rowArr[j];
      return obj;
    });
  }

