export function encodeByFirstAppearance(lst0, start = 0) {
  const codes = new Array(lst0.length);
  let nextCode = start;

  // map for primitive values -> code
  const primMap = new Map();
  // store complex (non-primitive) seen values with code, using deep equality when checking
  const complexSeen = []; // array of { value, code }

  const isPrimitive = (v) =>
    v === null ||
    v === undefined ||
    typeof v === 'string' ||
    typeof v === 'number' ||
    typeof v === 'boolean' ||
    typeof v === 'symbol' ||
    typeof v === 'bigint';

