  }

  const colNames = df0.columnNames();
  const rowsToCheck = Math.min(scanRows, df0.numRows());
  const boolCols = colNames.filter((col) => {
    // consider a column boolean if any non-null checked value is a boolean
    // and we do not see a non-boolean non-null value in the scanned rows.
