 * @param {string} dbName - Name of the database.
 * @param {string} storeName - Name of the object store (key-value collection).
 * @param {IDBValidKey} lowerBound - Lower boundary key.
 * @param {IDBValidKey} upperBound - Upper boundary key.
 * @param {Object} [opts] - Options.
 * @param {boolean} [opts.lowerOpen=false] - If true, exclude the lowerBound (open interval on lower side).
 * @param {boolean} [opts.upperOpen=false] - If true, exclude the upperBound (open interval on upper side).
 * @returns {Promise<Array<{key: IDBValidKey, value: any}>>} Array of { key, value } objects in key order.
 */
export async function fetchEntriesInRange(dbName, storeName, lowerBound, upperBound, opts = {}) {
  const { lowerOpen = false, upperOpen = false } = opts;

  if (lowerBound === undefined || upperBound === undefined) {
    throw new Error('Both lowerBound and upperBound must be provided.');
  }

  // If bounds are comparable and lower > upper, return empty early.
  try {
    // Only do a simple numeric/string comparison when possible.
    if (typeof lowerBound === typeof upperBound && (typeof lowerBound === 'number' || typeof lowerBound === 'string')) {
      if (lowerBound > upperBound) return [];
    }
  } catch (e) {
    // If comparison not meaningful, continue and let IndexedDB handle it.
  }

  // Open the DB; create the store if it doesn't exist (upgrade step).
  const db = await openDB(dbName, 1, {
    upgrade(upgradeDb) {
      if (!upgradeDb.objectStoreNames.contains(storeName)) {
        // create a simple key-value store using the key as the primary key
        upgradeDb.createObjectStore(storeName);
      }
    },
  });

  try {
    const range = IDBKeyRange.bound(lowerBound, upperBound, lowerOpen, upperOpen);

    // idb provides getAll and getAllKeys with a query argument (the range).
    // We call both and then zip them into key/value pairs. getAll and getAllKeys
    // return elements in the same order, so indexes align.
    const [values, keys] = await Promise.all([
      db.getAll(storeName, range),
      db.getAllKeys(storeName, range),
    ]);

    const result = keys.map((k, i) => ({ key: k, value: values[i] }));
    return result;
  } finally {
    db.close();
  }
}
