async function sumIdenticalColumns(data) {
    // Convert the data into a Tabulator Table
    const table = new Tabulator(null, {
        data: data,
        layout: "fitColumns",
    });

    // Get column definitions
    const columns = table.getColumns().map(column => column.getDefinition());

    // Create an object to hold the summed values
    const summedData = {};
    const headers = new Set();

    // Iterate over each row
    data.forEach(row => {
        // Iterate over each column definition
        columns.forEach(columnDef => {
            const field = columnDef.field;
            if (field) {
                headers.add(field);
                if (!summedData[field]) {
                    summedData[field] = 0;
                }
                summedData[field] += parseFloat(row[field]) || 0;
            }
        });
    });

    // Convert the summedData object back into an array format suitable for return
    const resultData = Array.from(headers).reduce((acc, header) => {
        acc[header] = summedData[header];
