/**
 * Determines whether any entry in a column matches a regular expression
 * Uses Danfo.js - a powerful data manipulation library for JavaScript
 * 
 * @param {Object} df0 - A Danfo.js DataFrame object
 * @param {string} var0 - The column name to search in
 * @param {string|RegExp} var1 - The regular expression pattern to match
 * @returns {boolean} - True if any entry matches the pattern, false otherwise
 */
function hasMatchInColumn(df0, var0, var1) {
  // Convert string pattern to RegExp if needed
  const regex = var1 instanceof RegExp ? var1 : new RegExp(var1);

  // Get the column values as an array
  const columnData = df0[var0].values;

  // Check if any value matches the regex pattern
  return columnData.some(value => {
    // Convert to string to handle non-string types
    return regex.test(String(value));
  });
}

