 *
 * @param {Array<Object>|aq.Table} df0 - Tabular dataset as an Arquero Table or an array of objects.
 * @param {string} var0 - Column name to check.
 * @param {string|RegExp} var1 - Regular expression (string or RegExp).
 * @returns {boolean} - True if any value in the column matches the regex, otherwise false.
 */
export function anyEntryMatches(df0, var0, var1) {
  if (!var0 || typeof var0 !== "string") {
    throw new TypeError("var0 must be a non-empty string column name");
  }

  // Build a RegExp object (if var1 is a string, treat it as a full pattern; no flags preserved)
  let re;
  if (var1 instanceof RegExp) {
    re = var1;
  } else if (typeof var1 === "string") {
    try {
      re = new RegExp(var1);
    } catch (err) {
      throw new Error("Invalid regular expression string provided in var1: " + err.message);
    }
  } else {
    throw new TypeError("var1 must be a RegExp or a string");
  }

  // If df0 is an Arquero table-like object (has numRows and objects methods), use it directly,
  // otherwise create an Arquero table from an array of objects.
  let table;
  if (df0 && typeof df0.numRows === "number" && typeof df0.objects === "function") {
