 * @returns {Array<Array<any>>} - Modified table with converted penultimate column
 */
function convertPenultimateCurrencyColumn(table, locale = 'en-US') {
    if (!Array.isArray(table) || table.length === 0) {
        return table;
    }

    // Create a number formatter for the specified locale
    const numberFormat = new Intl.NumberFormat(locale);

    // Get the formatting options to understand the locale's number format
    const formatOptions = numberFormat.resolvedOptions();

    // Helper function to parse localized number strings
    const parseLocalizedNumber = (str) => {
        if (str === null || str === undefined) {
            return NaN;
        }

        const stringValue = String(str).trim();

        // Remove all currency symbols and other non-numeric characters except decimal separator
        const decimalSeparator = formatOptions.locale === 'en-US' ? '.' : ',';
        const thousandSeparator = decimalSeparator === '.' ? ',' : '.';

        // Remove thousand separators
        let cleaned = stringValue.replace(new RegExp(`\\${thousandSeparator}`, 'g'), '');

        // Replace locale-specific decimal separator with standard decimal point
        cleaned = cleaned.replace(new RegExp(`\\${decimalSeparator}`), '.');

        // Remove all remaining non-numeric characters except minus sign and decimal point
        cleaned = cleaned.replace(/[^\d.-]/g, '');

