 * @param {string} [var1='var1'] - Name for the column that will hold the values.
 * @returns {Array<Object>} - New array of objects (unpivoted rows).
 */
export function unpivot(df0, lst0, var0 = "var0", var1 = "var1") {
  if (!Array.isArray(df0)) throw new TypeError("df0 must be an array of objects");
  if (!Array.isArray(lst0)) throw new TypeError("lst0 must be an array of strings");

