Code (ESM):
```
import sort from 'fast-sort';

/*
  sort2D:
  - data0: array of rows (each row can be an array or an object)
  - col0: array of column identifiers — for array-rows use numeric indices (0,1,2...), for object-rows use property names ('name','age',...)
  Returns:
  - var0: sorted array (a new array; original data0 is not mutated)
*/
export function sort2D(data0, col0) {
  // Defensive checks
  if (!Array.isArray(data0)) throw new TypeError('data0 must be an array of rows');
  if (!Array.isArray(col0) || col0.length === 0) {
    // nothing to sort by — return a shallow copy
    const var0 = data0.slice();
    return var0;
  }

  // create accessor functions for each column/key in col0
  const accessors = col0.map((col) => {
    // support numeric indices and string keys
    return (row) => {
      // row can be array or object
      try {
        return row[col];
      } catch (e) {
        return undefined;
      }
    };
  });

  // fast-sort mutates the input array; pass a shallow copy to avoid mutating original
  const var0 = sort(data0.slice()).by(accessors);

  return var0;
}
```

