const dfd = require("danfojs-node");

/**
 * Compute elementwise mean across multiple 2D numeric tables.
 *
 * @param {Array<Array<Array<number>>>} lst0 - Array of 2D numeric tables (each table is an array of rows, each row is an array of numbers).
 * @returns {Array<Array<number>>} A new 2D array where each entry is the mean of corresponding entries across input tables.
 *
 * Throws if lst0 is empty or if input tables have mismatched shapes or non-numeric entries.
 */
function meanAcrossTables(lst0) {
  if (!Array.isArray(lst0) || lst0.length === 0) {
    throw new Error("lst0 must be a non-empty array of 2D numeric tables.");
  }

  // Validate and determine shape from the first table
  const first = lst0[0];
  if (!Array.isArray(first) || first.length === 0 || !Array.isArray(first[0])) {
    throw new Error("Each table must be a 2D array (array of rows).");
  }
  const nRows = first.length;
  const nCols = first[0].length;

  // Validate shapes and numeric content
  for (let t = 0; t < lst0.length; t++) {
    const tbl = lst0[t];
    if (!Array.isArray(tbl) || tbl.length !== nRows) {
      throw new Error(`Table at index ${t} has wrong number of rows.`);
    }
    for (let i = 0; i < nRows; i++) {
      if (!Array.isArray(tbl[i]) || tbl[i].length !== nCols) {
        throw new Error(`Table at index ${t} has wrong number of columns in row ${i}.`);
      }
      for (let j = 0; j < nCols; j++) {
        const v = tbl[i][j];
        if (typeof v !== "number" || Number.isNaN(v) || !isFinite(v)) {
