  const dfs = lst0.map(tbl => new dfd.DataFrame(tbl));
  const sumDf = dfs.reduce((acc, df) => acc.add(df));

  // Compute mean by dividing by number of tables
  const meanDf = sumDf.div(lst0.length);

  // Return plain nested arrays
  return meanDf.values;
}

