      try {
        return Boolean(condition(x));
      } catch {
        return false;
      }
    };
  } else if (condition && typeof condition === 'object') {
    const { op, value } = condition;
    switch ((op || '').toString()) {
      case '==':
        predicate = (x) => Number.isFinite(x) && x == value; // eslint-disable-line eqeqeq
        break;
      case '===':
        predicate = (x) => Number.isFinite(x) && x === value;
        break;
      case '!=':
        predicate = (x) => Number.isFinite(x) && x != value; // eslint-disable-line eqeqeq
        break;
      case '!==':
        predicate = (x) => Number.isFinite(x) && x !== value;
        break;
      case '>':
        predicate = (x) => Number.isFinite(x) && x > value;
        break;
      case '>=':
        predicate = (x) => Number.isFinite(x) && x >= value;
        break;
      case '<':
        predicate = (x) => Number.isFinite(x) && x < value;
        break;
      case '<=':
        predicate = (x) => Number.isFinite(x) && x <= value;
        break;
      case 'in':
        predicate = (x) =>
          Number.isFinite(x) && Array.isArray(value) && value.some((v) => v === x);
        break;
      case 'between':
      case 'range':
        predicate = (x) =>
          Number.isFinite(x) &&
          Array.isArray(value) &&
          value.length >= 2 &&
          x >= Math.min(value[0], value[1]) &&
          x <= Math.max(value[0], value[1]);
        break;
      case 'mod':
        predicate = (x) =>
          Number.isFinite(x) &&
          Array.isArray(value) &&
          value.length >= 2 &&
          ((x % value[0]) === value[1]);
        break;
      default:
        throw new Error(`Unsupported condition op: ${String(op)}`);
    }
