 * @param {Array<Object>} rows - Array of row objects (each row has keys like "var0", "var1", ...).
 * @returns {Array<Object>} Aggregated rows as an array of objects.
 */
export function aggregateByVar0(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError("Input must be an array of row objects.");
  }
  if (rows.length === 0) return [];

  // Determine all column names found across rows (keeps robust if some rows have missing cols)
  const colSet = new Set();
  for (const r of rows) {
    if (r && typeof r === "object") {
      for (const k of Object.keys(r)) colSet.add(k);
    }
  }
  const allCols = Array.from(colSet);
  if (!allCols.includes("var0")) {
    throw new Error('Input rows must include a "var0" column.');
  }

  const valueCols = allCols.filter((c) => c !== "var0");

