import * as aq from 'arquero';

/**
 * Replace missing entries in categorical columns with the most frequent category (mode).
 *
 * Accepts either an Arquero table or an array of objects (records). Returns a new Arquero table.
 *
 * Options:
 *  - treatEmptyStringAsMissing (default true): consider "" as missing
 *  - extraMissingValues: array of additional string tokens to treat as missing (e.g. ['NA', 'N/A'])
 *  - maxUniqueForCategorical: columns with unique count <= this threshold (and not numeric) are treated as categorical
 *
 * Example:
 *   const filled = fillMissingCategoricalWithMode(df0);
 *
 * @param {aq.Table|Array<Object>} data - an Arquero table or array of objects
 * @param {Object} [opts]
 * @returns {aq.Table} new table with categorical missing values filled by mode
 */
export function fillMissingCategoricalWithMode(data, opts = {}) {
  const {
    treatEmptyStringAsMissing = true,
    extraMissingValues = ['NA', 'N/A', 'null', 'undefined'],
    maxUniqueForCategorical = 100,
  } = opts;

  const tbl = aq.table(data); // if data already a table, this is a no-op
  let out = tbl;

  const colNames = out.columnNames();

  // helper to detect missing value
  const isMissing = (v) => {
    if (v === null || v === undefined) return true;
    if (typeof v === 'number' && Number.isNaN(v)) return true;
    if (treatEmptyStringAsMissing && v === '') return true;
    if (typeof v === 'string' && extraMissingValues.includes(v)) return true;
    return false;
  };

  // helper to check numeric column (all non-missing values are numbers)
  const isNumericColumn = (arr) => {
    for (let v of arr) {
      if (isMissing(v)) continue;
      if (typeof v !== 'number' || !Number.isFinite(v)) return false;
    }
    // if there were no non-missing values, treat as non-numeric (so we can skip)
    return arr.some((v) => !isMissing(v));
  };

  for (const col of colNames) {
    const arr = out.array(col);

    // determine unique values among non-missing
    const uniq = new Set();
    for (const v of arr) {
      if (!isMissing(v)) uniq.add(v);
      if (uniq.size > maxUniqueForCategorical) break;
    }

    // decide whether to treat this column as categorical:
    // - not numeric (i.e., contains non-number values)
    // - and unique count is reasonably small (<= maxUniqueForCategorical)
    const numeric = isNumericColumn(arr);
    const uniqueCount = uniq.size;
    const isCategorical = !numeric && uniqueCount > 0 && uniqueCount <= maxUniqueForCategorical;

    if (!isCategorical) continue;

    // compute frequencies (mode) ignoring missing values
    const freq = new Map();
    for (const v of arr) {
      if (isMissing(v)) continue;
      const key = v;
      freq.set(key, (freq.get(key) || 0) + 1);
    }

    if (freq.size === 0) continue; // nothing to fill

    // select mode (if ties, pick the first encountered with max count)
    let mode = null;
    let maxCount = -1;
    for (const [key, count] of freq.entries()) {
      if (count > maxCount) {
        maxCount = count;
        mode = key;
      }
    }

    // build new column array with missing values replaced by mode
    const newCol = arr.map((v) => (isMissing(v) ? mode : v));

    // assign new column (Arquero returns a new table)
    out = out.assign({ [col]: newCol });
  }

  return out;
}

Usage example:

