  // Compute aggregations based on the specified function
  const aggregated = grouped.map(([key, values]) => {
    const valuesArray = values.map(d => d[valueField]);

    // Apply aggregation (using D3's mean, sum, etc.)
    switch (aggFunction.toLowerCase()) {
