Function (ES module style):

```javascript
// Example: save as countColumnMatches.js
import * as aq from 'arquero';

/**
 * Count how many entries in a specified column of a tabular dataset match a given value.
 *
 * @param {Array<Object>|aq.Table} data - Array of row objects or an Arquero Table.
 * @param {string} column - Column name to check.
 * @param {string|number|boolean|RegExp} value - Value to match (string, number, boolean, or RegExp).
 * @param {Object} [options] - Optional settings.
 * @param {'strict'|'loose'|'includes'|'regex'} [options.mode='strict'] - Matching mode:
 *        'strict'  => ===,
 *        'loose'   => ==,
 *        'includes'=> substring (both sides cast to string),
 *        'regex'   => value must be RegExp.
 * @param {boolean} [options.caseInsensitive=false] - If true and both sides are strings, compare case-insensitively.
 * @returns {number} Count of rows where column matches value by the chosen mode.
 *
 * Throws if column is missing or if invalid combination of mode and value is provided.
 */
export function countColumnMatches(data, column, value, options = {}) {
  const { mode = 'strict', caseInsensitive = false } = options;

  if (!column || typeof column !== 'string') {
    throw new Error('column must be a non-empty string');
  }

  // Accept either an Arquero table or an array of objects
  const isTableLike = data && typeof data.filter === 'function' && typeof data.numRows === 'function';
  const table = isTableLike ? data : aq.table(data || []);

  // Validate mode/value combos
  if (mode === 'regex' && !(value instanceof RegExp)) {
    throw new Error("mode 'regex' requires a RegExp value");
  }
  if (mode !== 'regex' && value instanceof RegExp) {
    throw new Error('If value is a RegExp, set mode to "regex"');
  }

  // Build predicate for arquero filter
  const predicate = (row) => {
    const cell = row[column];

    // treat undefined columns gracefully
    if (typeof cell === 'undefined') return false;

    if (mode === 'strict') {
      if (caseInsensitive && typeof cell === 'string' && typeof value === 'string') {
        return cell.toLowerCase() === value.toLowerCase();
      }
      return cell === value;
    }

    if (mode === 'loose') {
      // eslint-disable-next-line eqeqeq
      if (caseInsensitive && typeof cell === 'string' && typeof value === 'string') {
        return cell.toLowerCase() == value.toLowerCase(); // loose with lowered strings
      }
      // loose comparison using ==
      // eslint-disable-next-line eqeqeq
      return cell == value;
    }

    if (mode === 'includes') {
      // both sides cast to string
      const sCell = String(cell);
      const sValue = String(value);
      if (caseInsensitive) {
        return sCell.toLowerCase().includes(sValue.toLowerCase());
      }
      return sCell.includes(sValue);
    }

    if (mode === 'regex') {
      return value.test(String(cell));
    }

    // fallback
    return false;
  };

  // Use Arquero filter and count rows
  const matched = table.filter(predicate);
  return matched.numRows();
}
```

