```javascript
// Requires: npm install duckdb
const duckdb = require('duckdb');

/**
 * groupCounts(df, keyColumns)
 *
 * Determine, for each distinct combination of values across keyColumns in df,
 * how many rows belong to that group.
 *
 * Inputs:
 * - df: array of objects, e.g. [{a:1, b:2}, {a:1, b:3}, ...]
 *       All rows do not strictly need identical keys; missing values will be treated as NULL.
 * - keyColumns: array of column names to group by, e.g. ['a','b'] or ['category']
 *
 * Returns: Promise resolving to an array of objects, each with the key columns and a `count` field.
 * Example returned row: { a: '1', b: '2', count: 5 }
 *
 * Note: All values are inserted as TEXT to simplify type handling. Null/undefined become NULL.
 */
async function groupCounts(df, keyColumns) {
  if (!Array.isArray(df)) throw new TypeError('df must be an array of objects');
  if (!Array.isArray(keyColumns) || keyColumns.length === 0) throw new TypeError('keyColumns must be a non-empty array of column names');

  if (df.length === 0) {
    // Return empty result for no rows.
    return [];
  }

  // Determine union of all column names across rows to form the table schema
  const columnSet = new Set();
  for (const row of df) {
    if (row && typeof row === 'object') {
      for (const k of Object.keys(row)) columnSet.add(k);
    }
  }
  const allColumns = Array.from(columnSet);
  // Quote helper for SQL identifiers
  const quoteIdent = (s) => `"${String(s).replace(/"/g, '""')}"`;

  // Create in-memory DuckDB and a connection
  const db = new duckdb.Database(':memory:');
  const conn = db.connect();

  // Promisify run/all operations used below
  const runAsync = (sql, params = []) =>
    new Promise((resolve, reject) => conn.run(sql, params, (err) => (err ? reject(err) : resolve())));
  const allAsync = (sql, params = []) =>
    new Promise((resolve, reject) => conn.all(sql, params, (err, rows) => (err ? reject(err) : resolve(rows))));

  // Build and create table with all columns typed as TEXT (to keep simple)
  const colsSQL = allColumns.map(c => `${quoteIdent(c)} TEXT`).join(', ');
  const createSQL = `CREATE TABLE __input (${colsSQL})`;
  await runAsync(createSQL);

  // Insert all rows using parameterized statements
  const colsQuoted = allColumns.map(quoteIdent).join(', ');
  const placeholders = allColumns.map(() => '?').join(', ');
  const insertSQL = `INSERT INTO __input (${colsQuoted}) VALUES (${placeholders})`;

  for (const row of df) {
    const params = allColumns.map(col => {
      const v = row ? row[col] : undefined;
      // Treat undefined as NULL; else cast to string to insert as TEXT
      return v === undefined ? null : String(v);
    });
    await runAsync(insertSQL, params);
  }

  // Validate requested keyColumns exist in the table
  for (const kc of keyColumns) {
    if (!allColumns.includes(kc)) {
      // If a key column isn't present in any row, the result is an empty grouping (NULL column)
      // We still allow it, the query will return groups with NULL for that column if present.
      // But warn the user:
      // (not throwing, just a console warning)
      console.warn(`Warning: key column "${kc}" not present in input rows; it will be NULL in results.`);
    }
  }

  // Run GROUP BY query
  const groupColsSql = keyColumns.map(quoteIdent).join(', ');
  const query = `SELECT ${groupColsSql}, COUNT(*) AS count FROM __input GROUP BY ${groupColsSql}`;
  const rows = await allAsync(query);

  // Convert count to number, leave keys as strings/null (they were inserted as TEXT)
  const out = rows.map(r => {
    const obj = {};
    for (const kc of keyColumns) {
      obj[kc] = r[kc] === null ? null : r[kc]; // keep original textual form (could be '1' etc.)
    }
    obj.count = typeof r.count === 'number' ? r.count : Number(r.count);
    return obj;
  });

  // Close connection (duckdb module does not provide a direct close on connection in older API;
  // garbage collection frees resources. If your version exposes conn.close(), call it here.)
  try { if (typeof conn.close === 'function') conn.close(); } catch (_) {}

  return out;
}

// Example usage:
(async () => {
  const df = [
    { category: 'A', sub: 'x', value: 10 },
    { category: 'A', sub: 'x', value: 12 },
    { category: 'A', sub: 'y', value: 8 },
    { category: 'B', sub: 'x', value: 7 },
    { category: 'B', sub: 'x', value: 2 },
  ];

  const res = await groupCounts(df, ['category', 'sub']);
  console.log(res);
  // Example output (order may vary):
  // [ { category: 'A', sub: 'x', count: 2 },
  //   { category: 'A', sub: 'y', count: 1 },
  //   { category: 'B', sub: 'x', count: 2 } ]
})();
```

Notes and alternatives:
- This implementation stores everything as TEXT to avoid schema inference complexity; if you need to preserve native types (numbers, dates), you can extend the code to detect types and create appropriate column types before inserting.
- Using DuckDB allows you to scale to larger datasets and use SQL for flexible aggregations; if you prefer a pure-JS approach without native modules, simple grouping can also be performed using a Map/loop or libraries like d3-array or lodash.

