// Requires: npm install fast-sort
import sort from 'fast-sort';

/**
 * Sort each inner list according to a mapping that defines the desired order.
 *
 * - mapping may be:
 *    - an array: e.g. ['a','b','c'] meaning 'a' comes before 'b' before 'c'
 *    - an object: e.g. { a: 0, b: 1, c: 2 } where values are numeric ranks
 * - options:
 *    - unknownPlacement: 'end' (default) | 'start' — where items not present in mapping go
 *
 * Returns a NEW array of sorted inner arrays (does not mutate input lists).
 */
export function sortInnerListsByMapping(lists, mapping, options = {}) {
  const { unknownPlacement = 'end' } = options;

  // Build rank map
  const rankMap = new Map();
  if (Array.isArray(mapping)) {
    mapping.forEach((val, idx) => rankMap.set(val, idx));
  } else if (mapping && typeof mapping === 'object') {
    Object.entries(mapping).forEach(([key, val]) => rankMap.set(key, Number(val)));
  } else {
    throw new TypeError('mapping must be an array or an object');
  }

  // Determine ranks for unknown items
  const ranks = Array.from(rankMap.values());
  const maxRank = ranks.length ? Math.max(...ranks) : -1;
  const unknownRank = unknownPlacement === 'start' ? maxRank - 1 : maxRank + 1;

  // For stable behavior: fast-sort is stable, so items with same rank preserve original order.
  return lists.map(inner => {
    // If inner is not an array, just return it unchanged (or you could throw)
    if (!Array.isArray(inner)) return inner;
    // Use selector function to map element -> rank
    return sort(inner).by(item => (rankMap.has(item) ? rankMap.get(item) : unknownRank));
  });
}
