    throw new TypeError('mapping must be an Object or a Map');
  }

  // Build entries with original indices (in insertion order for objects and Maps)
  const entries = [];
  if (mapping instanceof Map) {
    let idx = 0;
    for (const [key, value] of mapping) {
      entries.push({ key, value, index: idx++ });
    }
  } else if (typeof mapping === 'object') {
    const keys = Object.keys(mapping);
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      entries.push({ key, value: mapping[key], index: i });
    }
  } else {
    throw new TypeError('mapping must be a plain Object or a Map');
