  if (n === 0) return [];

  // Fast path for primitive-like comparisons: use a Set
  if (typeof equals !== 'function') {
    const secSet = new Set(secondary);
    // filter keeps order; take gets the first n
    return take(filter(primary, item => !secSet.has(item)), n);
  }

