Code:

```javascript
// Requires: npm install arquero
import * as aq from 'arquero';

/**
 * Remove rows that are identical to the immediately previous row.
 * Keeps the first row of each run of consecutive duplicates.
 *
 * @param {aq.Table|Array<Object>} tableOrArray - an Arquero Table or an array of row objects
 * @returns {aq.Table} a new Arquero Table with consecutive duplicate rows removed
 */
export function dropConsecutiveDuplicates(tableOrArray) {
  // Ensure we have an Arquero table
  const tbl = aq.table(tableOrArray);
  const cols = tbl.columnNames();

  // If no columns (empty table), just return the table
  if (cols.length === 0) return tbl;

  // Build an expression that checks equality of each column to its lagged value
  const isDupExpr = aq.op.and(
    ...cols.map((c) => aq.op.eq(aq.op.col(c), aq.op.lag(aq.op.col(c))))
  );

  // Derive a temporary boolean column marking consecutive duplicates,
  // filter them out, then select original columns to drop the helper column.
  return tbl
    .derive({ __is_dup__: isDupExpr })
    .filter(aq.op.not(aq.op.col('__is_dup__')))
    .select(...cols);
}
```

Usage examples:

```javascript
