  { id: 1, x: 'a' },
  { id: 1, x: 'a' }, // duplicate of previous -> removed
  { id: 2, x: 'b' },
  { id: 2, x: 'b' }, // duplicate -> removed
  { id: 1, x: 'a' }  // not removed because previous is {2,'b'} (not identical)
];

