Below is a compact, self-contained JavaScript function that uses the modern data-wrangling library Arquero (v4+, active in 2023+) to add new columns to a two-dimensional data object. The function accepts either an Arquero Table or a standard array-of-objects (rows) as df0 and a list lst0 of column identifiers; it returns an updated Arquero Table (or an array of row objects if requested). New columns are initialized to an "empty" value (default null).

Install Arquero first:
- npm: npm install arquero

Code:

import * as aq from "arquero";

/**
 * Add new columns to a 2D data object (Arquero Table or array-of-objects).
 *
 * @param {Object|Array} df0 - An Arquero Table or an array of row objects.
 * @param {Array<string>} lst0 - List of column names to add.
 * @param {Object} [opts] - Options:
 *   - emptyValue: value to use for new cells (default: null)
 *   - skipIfExists: if true, do not overwrite existing columns (default: false)
 *   - returnAs: 'table' (Arquero Table) or 'array' (array of objects) (default: 'table')
 * @returns {Object|Array} Updated Arquero Table or array-of-objects.
 */
function addEmptyColumns(df0, lst0, opts = {}) {
  const { emptyValue = null, skipIfExists = false, returnAs = "table" } = opts;

  // Normalize to an Arquero table (if df0 already is a table, keep it)
  const isArqueroTable = df0 && typeof df0.columnNames === "function";
  const tbl = isArqueroTable ? df0 : aq.table(df0 || []);

  // Build assign mapping for arquero Table.assign.
  const existing = new Set(tbl.columnNames());
  const assigns = {};
  for (const name of lst0) {
    if (skipIfExists && existing.has(name)) continue;
    // Use a function so the same value is produced for every row
    assigns[name] = () => emptyValue;
  }

  // Assign returns a new Table (Arquero is immutable)
  const newTbl = tbl.assign(assigns);

  return returnAs === "array" ? newTbl.objects() : newTbl;
}

Example usage:

// Using an array of objects, returning an Arquero Table
const rows = [{ id: 1, x: 10 }, { id: 2, x: 20 }];
let updatedTable = addEmptyColumns(rows, ["y", "z"]); // returns a Table
console.log(updatedTable.columnNames()); // ['id','x','y','z']

// Using an Arquero Table, returning an array of objects
const t = aq.table(rows);
const updatedArray = addEmptyColumns(t, ["y", "z"], { returnAs: "array", emptyValue: "" });
console.log(updatedArray); // [{id:1,x:10,y:"",z:""}, {id:2,x:20,y:"",z:""}]

Notes:
- Arquero tables are immutable; addEmptyColumns returns a new Table (or array) and does not mutate the original Table object.
- Customize emptyValue (null, undefined, "", 0, etc.) as needed.
- Arquero is a modern, efficient library for tabular data manipulation (see https://github.com/uwdata/arquero).

