    B.forEach((value, index) => {
        orderMap.set(value, index);
    });

    // Sort A based on the order defined in B, placing unmatched items at the beginning
    return A.sort((a, b) => {
        const aIndex = orderMap.get(a);
        const bIndex = orderMap.get(b);

        // If a or b are not in B, place them before elements that are in B
