        if (bIndex === undefined && aIndex !== undefined) return 1;

        // If both a and b are in B, sort them by their defined order
        if (aIndex !== undefined && bIndex !== undefined) return aIndex - bIndex;

        // If neither a nor b are in B, maintain their relative order from A
        return 0;
    });
