# Sort List by Custom Order with Unmatched Items First

Here's a self-contained solution using the `Map` data structure for O(1) lookups, making it efficient even with large lists:

```javascript
/**
 * Sorts list A according to the order defined in list B.
 * Items in A not present in B are placed at the beginning.
 * 
 * @param {Array} A - The list to be sorted
 * @param {Array} B - The reference list that defines the sort order (must be pre-sorted)
 * @returns {Array} - A new sorted array
 * 
 * Time Complexity: O(n + m) where n = length of A, m = length of B
 * Space Complexity: O(m) for the Map
 */
function sortByCustomOrder(A, B) {
  // Create a Map for O(1) index lookups in B
  // This makes the solution efficient even when B is very large
  const orderMap = new Map(B.map((item, index) => [item, index]));

  return A.sort((a, b) => {
    const aInOrder = orderMap.has(a);
    const bInOrder = orderMap.has(b);

    // If both items are in B, compare by their order in B
    if (aInOrder && bInOrder) {
      return orderMap.get(a) - orderMap.get(b);
    }

    // If only a is in B, b comes first (b is unmatched)
    if (!aInOrder && bInOrder) {
      return 1;
    }

    // If only b is in B, a comes first (a is unmatched)
    if (aInOrder && !bInOrder) {
      return -1;
    }

    // If neither is in B, maintain relative order (stable sort)
    return 0;
  });
}

// ============================================================================
// EXAMPLES
// ============================================================================

// Example 1: Basic usage
const A1 = ['apple', 'banana', 'cherry', 'date', 'elderberry'];
const B1 = ['cherry', 'apple', 'date'];
console.log('Example 1:');
console.log('A:', A1);
console.log('B:', B1);
console.log('Result:', sortByCustomOrder(A1, B1));
// Output: ['banana', 'elderberry', 'cherry', 'apple', 'date']

// Example 2: Numbers
const A2 = [5, 1, 3, 2, 4, 6, 7];
const B2 = [3, 1, 2];
console.log('\nExample 2:');
console.log('A:', A2);
console.log('B:', B2);
console.log('Result:', sortByCustomOrder(A2, B2));
// Output: [4, 5, 6, 7, 3, 1, 2]

// Example 3: All items in A are in B
