const B3 = ['a', 'b', 'z'];
console.log('\nExample 3:');
console.log('A:', A3);
console.log('B:', B3);
console.log('Result:', sortByCustomOrder(A3, B3));
// Output: ['a', 'b', 'z']

// Example 4: None of the items in A are in B
