const B4 = ['a', 'b', 'c'];
console.log('\nExample 4:');
console.log('A:', A4);
console.log('B:', B4);
console.log('Result:', sortByCustomOrder(A4, B4));
// Output: ['x', 'y', 'z'] (unchanged, stable sort)

// Example 5: Large B list (efficiency test)
