import { z } from "zod";

/**
 * Extracts entries from parent_dict whose numeric keys are in [2, 4] (inclusive).
 * Accepts either a plain object or a Map. Returns the same container type as input.
 *
 * Examples:
 *   extractRange({ "1": "a", "2": "b", "3": "c", "5": "d" }) -> { "2": "b", "3": "c" }
 *   extractRange(new Map([[2, 'b'], [3, 'c'], [5, 'd']])) -> Map {2 => 'b', 3 => 'c'}
 *
 * @param {Object|Map} parent_dict - associative container (object or Map)
 * @returns {Object|Map} filtered container with only entries whose keys are numeric in [2,4]
 */
export function extractRange(parent_dict) {
  // Build entries array regardless of input type
  const entries = parent_dict instanceof Map
    ? Array.from(parent_dict.entries())
    : Object.entries(parent_dict);

  // Validate the shape: array of [key, value] tuples (key can be string or number)
  const EntrySchema = z.tuple([z.union([z.string(), z.number()]), z.any()]);
  const EntriesSchema = z.array(EntrySchema);

