  const parsed = EntriesSchema.parse(entries);

  // Filter by numeric key between 2 and 4 inclusive
  const filtered = parsed.filter(([key]) => {
    const n = Number(key);
    return Number.isFinite(n) && n >= 2 && n <= 4;
  });

  // Return same type as input
