```javascript
// Example Node.js / ES module usage
// npm install arquero
import { table } from 'arquero';

/**
 * Determine which columns contain at least one missing value.
 *
 * @param {Array<Object>} rows - Array of row objects (tabular dataset).
 * @returns {{ columnsWithMissing: string[], hasMissing: Record<string, boolean> }}
 *          - columnsWithMissing: array of column names that contain missing values
 *          - hasMissing: map of columnName -> boolean (true if the column has >=1 missing)
 */
export function findColumnsWithMissing(rows) {
  // Normalize input through Arquero (makes it easier if you want to use other aq features)
  // If input is already an array of objects, table(rows).objects() returns similar data.
  const t = table(rows || []);
  const rowObjs = t.objects();

  // Collect all column names present across all rows
  const colSet = new Set();
  for (const r of rowObjs) {
    for (const k of Object.keys(r)) colSet.add(k);
  }
  // Also handle the case of zero rows but known columns (rare). If rows is empty, return empty result.
  if (rowObjs.length === 0) {
    return { columnsWithMissing: [], hasMissing: {} };
  }

  const cols = Array.from(colSet);
  const hasMissing = Object.create(null);

  // Helper to detect missing values
  const isMissing = (v) => {
    if (v === null || v === undefined) return true;
    if (typeof v === 'number' && Number.isNaN(v)) return true;
    // If you want to treat empty strings as missing, uncomment:
    // if (v === '') return true;
    return false;
  };

  // For each column, scan rows to see if any value is missing.
  for (const col of cols) {
    let found = false;
    for (const r of rowObjs) {
      // If row doesn't have the key at all, treat as missing
      if (!Object.prototype.hasOwnProperty.call(r, col)) {
        found = true;
        break;
      }
      if (isMissing(r[col])) {
        found = true;
        break;
      }
    }
    hasMissing[col] = found;
  }

  const columnsWithMissing = cols.filter((c) => hasMissing[c]);

  return { columnsWithMissing, hasMissing };
}
