    ? str1.map(String)
    : String(str1).split(',').map(s => s.trim()).filter(Boolean);

  // Temporary column name for the split result
  const tmpCol = `__split_tmp_${str0}`;

  // Build initial table
  let tbl = aq.table(data);

  // Add temporary array column by splitting the target column, then unroll (explode)
  tbl = tbl
    .derive({ [tmpCol]: d => (d[str0] == null ? [] : op.split(d[str0], var1)) })
    .unroll(tmpCol)
    // map the unrolled value back into the original column name
    .derive({ [str0]: d => d[tmpCol] });

  // Ensure any columns requested but not present are added (with undefined values)
  const existingCols = tbl.columnNames();
