    !priorityOrder.includes(col)
  );

  // Combine: priority columns first, then others in original order
  const finalColumnOrder = [...priorityColumnsPresent, ...otherColumns];

  // Select columns in the desired order
  return merged.loc({ columns: finalColumnOrder });
