/**
 * Merge new columns into a base table and reorder columns so that priorityCols
 * appear (in that order) at the front while other columns retain their original relative order.
 *
 * @param {Array<Object>} baseTable
 * @param {Object} newCols - mapping columnName -> (Array | function(row, i) | singleValue)
 * @param {Array<string>} priorityCols - column names to bring forward in the given order
 * @returns {Array<Object>} merged table with column order preserved as described
 */
export function mergeColumnsWithPriority(baseTable, newCols = {}, priorityCols = []) {
  // Defensive: if baseTable empty, but newCols present, we may still create empty rows.
  const rowCount = baseTable.length || 0;

  // 1) Build shallow copies of base rows so we don't mutate input
  const mergedRows = baseTable.map(row => ({ ...row }));

  // If there are no rows but newCols are arrays, we'll still create rows for any max length.
  let maxLen = rowCount;
  for (const v of Object.values(newCols)) {
    if (Array.isArray(v)) maxLen = Math.max(maxLen, v.length);
  }
  // If base had no rows but newCols have arrays, create empty base rows to fill
  if (rowCount === 0 && maxLen > 0) {
    for (let i = 0; i < maxLen; i++) mergedRows.push({});
  }

  // 2) Merge new columns into each row, in the order of Object.keys(newCols)
  for (const colName of Object.keys(newCols)) {
    const src = newCols[colName];
    if (Array.isArray(src)) {
      // assign per-row from array; if shorter than rows, undefined for missing
      for (let i = 0; i < mergedRows.length; i++) {
        mergedRows[i][colName] = src[i];
      }
    } else if (typeof src === 'function') {
      for (let i = 0; i < mergedRows.length; i++) {
        mergedRows[i][colName] = src(mergedRows[i], i);
      }
    } else {
      // broadcast single value
      for (let i = 0; i < mergedRows.length; i++) {
        mergedRows[i][colName] = src;
      }
    }
  }

  // 3) Compute mergedCols in original relative order:
  // Walk rows in order and record first-seen keys (Object.keys preserves insertion order).
  const seen = new Set();
  const mergedCols = [];
  for (const row of mergedRows) {
    for (const k of Object.keys(row)) {
      if (!seen.has(k)) {
        seen.add(k);
        mergedCols.push(k);
      }
    }
  }

  // 4) Compute final column order:
  // Take priorityCols in the given order but only those present, then append remaining columns in their original order.
  const presentPriority = intersection(priorityCols, mergedCols);
  const remaining = difference(mergedCols, presentPriority);
  const finalCols = [...presentPriority, ...remaining];

  // 5) Rebuild rows with keys in finalCols order (so insertion order of keys matches)
  const reordered = mergedRows.map(row => {
    const out = {};
    for (const c of finalCols) {
      // include key even if undefined (keeps consistent column set)
      out[c] = row.hasOwnProperty(c) ? row[c] : undefined;
    }
    return out;
  });

  return reordered;
}

