import * as aq from "arquero";

/**
 * Group a table by var0 and produce a new table that simulates a hierarchical (multi-level)
 * index by adding two index columns:
 *   - level0: the grouping key (value of var0)
 *   - level1: integer index of the row within its group (0-based)
 *
 * Input df0 may be an Arquero Table or an array of plain objects (records).
 * Returns an Arquero Table with added columns: level0, level1.
 *
 * Example:
 *   const df = [{var0: 'A', x:1}, {var0:'B', x:2}, {var0:'A', x:3}];
 *   const result = groupByToMultiIndex(df, 'var0');
 *   result.print();
 */
export function groupByToMultiIndex(df0, var0, {level0Name = "level0", level1Name = "level1"} = {}) {
  // ensure we have an Arquero table
  const table = aq.table(df0);

  // get plain objects for grouping
  const objs = table.objects();

  // build groups preserving input order
  const groups = new Map();
  for (const row of objs) {
    const key = row[var0];
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(row);
  }

  // flatten into rows that include multi-level index columns
  const flattened = [];
  for (const [key, rows] of groups) {
    let i = 0;
    for (const r of rows) {
      // copy row to avoid mutating original
      const newRow = { ...r };
      newRow[level0Name] = key;
      newRow[level1Name] = i++;
      flattened.push(newRow);
    }
  }

  // return an Arquero table with the added index columns
  return aq.table(flattened);
}
```

