Usage:
1) Install mathjs (example):
   npm install mathjs@11

2) Save the code below to a file (e.g., solve2.js) and run with node.

Code:

```javascript
// Example: Node.js script. Requires mathjs (v11+ recommended).
// npm install mathjs@11

const math = require('mathjs');

/**
 * Solve two coupled nonlinear equations f(x,y) = 0 using Newton-Raphson.
 *
 * @param {function(Array<number>): Array<number>} f - function that accepts [x,y] and returns [f1,f2]
 * @param {Array<number>} x0 - initial guess [x0, y0]
 * @param {object} [opts] - options: tol (stopping tolerance), maxIter, h (finite-diff step), verbose
 * @returns {object} {root: [x,y], iterations, converged, lastF, lastJacobian}
 */
function solveTwoEquations(f, x0, opts) {
  const opt = Object.assign({ tol: 1e-8, maxIter: 50, h: 1e-6, verbose: false }, opts);
  if (!Array.isArray(x0) || x0.length !== 2) throw new Error('x0 must be an array of length 2');
  let x = [x0[0], x0[1]];

  function evalF(x) {
    const fx = f([x[0], x[1]]);
    if (!Array.isArray(fx) || fx.length !== 2) throw new Error('f must return an array of length 2');
    return [Number(fx[0]), Number(fx[1])];
  }

  function numericJacobian(x) {
    const h = opt.h;
    const J = [[0, 0], [0, 0]];
    const f0 = evalF(x);
    for (let j = 0; j < 2; j++) {
      const xp = [x[0], x[1]];
      const xm = [x[0], x[1]];
      xp[j] += h;
      xm[j] -= h;
      const fp = evalF(xp);
      const fm = evalF(xm);
      // central difference column j
      J[0][j] = (fp[0] - fm[0]) / (2 * h);
      J[1][j] = (fp[1] - fm[1]) / (2 * h);
    }
    return J;
  }

  let converged = false;
  let lastF = null;
  let lastJ = null;

  for (let iter = 1; iter <= opt.maxIter; iter++) {
    const F = evalF(x);
    lastF = F.slice();
    const normF = Math.hypot(F[0], F[1]);
    if (opt.verbose) console.log(`Iter ${iter}: x=${x.map(v=>v.toPrecision(8))}, F=${F.map(v=>v.toExponential(3))}, ||F||=${normF.toExponential(3)}`);

    if (normF <= opt.tol) {
      converged = true;
      return { root: x.slice(), iterations: iter - 1, converged, lastF, lastJacobian: lastJ };
    }

    const J = numericJacobian(x);
    lastJ = [J[0].slice(), J[1].slice()];

    // Solve J * delta = -F. Use math.lusolve (2x2 system).
    const A = math.matrix([[J[0][0], J[0][1]], [J[1][0], J[1][1]]]);
    const b = math.matrix([[-F[0]], [-F[1]]]);

    let delta;
    try {
      const sol = math.lusolve(A, b); // returns 2x1 matrix
      delta = [Number(sol.get([0, 0])), Number(sol.get([1, 0]))];
    } catch (err) {
      // Jacobian singular or near-singular: try damped (Levenberg-like) solves
      if (opt.verbose) console.warn('Jacobian solve failed (singular?). Trying damped solves...');
      let solved = false;
      for (const lam of [1e-6, 1e-4, 1e-2, 0.1, 1, 10]) {
        try {
          const Jd = math.add(A, math.multiply(lam, math.identity(2)));
          const sol = math.lusolve(Jd, b);
          delta = [Number(sol.get([0, 0])), Number(sol.get([1, 0]))];
          solved = true;
          if (opt.verbose) console.log(`Damped solve succeeded with lambda=${lam}`);
          break;
        } catch (err2) {
          // continue trying other lambda
        }
      }
      if (!delta) {
        if (opt.verbose) console.error('Failed to solve linear step: Jacobian may be singular. Aborting.');
        return { root: x.slice(), iterations: iter - 1, converged: false, lastF, lastJacobian: lastJ };
      }
    }

    // update: x = x + delta
    x = [x[0] + delta[0], x[1] + delta[1]];
    const deltaNorm = Math.hypot(delta[0], delta[1]);
    if (deltaNorm <= opt.tol) {
      converged = true;
      return { root: x.slice(), iterations: iter, converged, lastF, lastJacobian: lastJ };
    }
  }

  // reached maxIter
  return { root: x.slice(), iterations: opt.maxIter, converged: false, lastF, lastJacobian: lastJ };
}

// ---------------------- Example usage ----------------------
// Example system:
//   f1(x,y) = x^2 + y^2 - 4
//   f2(x,y) = x - y - 1
// Has root near [x= (1 + sqrt(17))/2 ~ 2.56155, y = x - 1 ~ 1.56155].
// We'll start from initial guess [1, 1].

function example() {
  const f = ([x, y]) => [x * x + y * y - 4, x - y - 1];
  const x0 = [1, 1];
  const result = solveTwoEquations(f, x0, { tol: 1e-12, maxIter: 50, verbose: true });
  console.log('Result:', result);
}

if (require.main === module) {
  example();
}

// Export for use as a module
module.exports = { solveTwoEquations };
