```javascript
// Requires: npm install luxon@^3.0.0
import { DateTime } from "luxon";

/**
 * Segment entries of column `colName` in dataset `df` into intervals defined by `boundaries`.
 * - If boundaries parse as valid ISO dates, column values are parsed as dates.
 * - Otherwise values/boundaries are treated as numbers.
 *
 * @param {Array<Object>} df - array of row objects (the dataset)
 * @param {string} colName - name of column to segment (default 'str0')
 * @param {Array<string|number>} boundaries - sorted or unsorted list of boundary values (lst0)
 * @param {Object} [opts] - options
 *   - outputCol {string} name of added column (default 'interval')
 *   - includeUpper {boolean} whether upper bound is inclusive (default false -> right-exclusive)
 *   - underLabel {string|null} label for values < first boundary (default '<bound0')
 *   - overLabel {string|null} label for values >= last boundary (default '>=boundLast')
 *   - formatDate {function|false} formatter for date boundaries (default ISO date)
 *
 * @returns {Array<Object>} new array with an added column containing interval labels
 */
export function segmentColumn(df, colName = "str0", boundaries, opts = {}) {
  if (!Array.isArray(df)) throw new TypeError("df must be an array of objects");
  if (!Array.isArray(boundaries) || boundaries.length < 2)
    throw new TypeError("boundaries must be an array with at least two elements");

  const {
    outputCol = "interval",
    includeUpper = false,
    underLabel = null,
    overLabel = null,
    formatDate = null,
  } = opts;

  // Helper: test if all boundaries parse as ISO dates (Luxon)
  const allDates = boundaries.every((b) => {
    const s = typeof b === "string" || typeof b === "number" ? String(b) : null;
    if (s === null) return false;
    return DateTime.fromISO(s).isValid;
  });

  // Normalize and sort boundaries
  let bounds; // array of comparable numbers (millis for dates or numbers)
  let labelify; // function to make readable labels from a boundary value
  if (allDates) {
    // parse to millis
    bounds = boundaries.map((b) => DateTime.fromISO(String(b)).toMillis());
    bounds.sort((a, b) => a - b);
    labelify = (millis) =>
      formatDate
        ? formatDate(DateTime.fromMillis(millis))
        : DateTime.fromMillis(millis).toISODate(); // default ISO date string
  } else {
    // numeric mode
    bounds = boundaries.map((b) => {
      const n = typeof b === "number" ? b : Number(String(b));
      if (!Number.isFinite(n)) throw new TypeError("Non-numeric boundary encountered");
      return n;
    });
    bounds.sort((a, b) => a - b);
    labelify = (n) => String(n);
  }

  // Create interval labels array for intervals between bounds[i] and bounds[i+1]
  const intervalLabels = [];
  for (let i = 0; i < bounds.length - 1; i++) {
    const left = labelify(bounds[i]);
    const right = labelify(bounds[i + 1]);
    const leftBracket = "[";
    const rightBracket = includeUpper ? "]" : ")";
    intervalLabels.push(`${leftBracket}${left}, ${right}${rightBracket}`);
  }
  const defaultUnderLabel = `< ${labelify(bounds[0])}`;
  const defaultOverLabel = `${includeUpper ? ">=" : ">"} ${labelify(bounds[bounds.length - 1])}`;

  const under = underLabel ?? defaultUnderLabel;
  const over = overLabel ?? defaultOverLabel;

  // Parser for row values into comparable numeric form (millis or number)
  const parseValue = (v) => {
    if (v === null || v === undefined || v === "") return NaN;
    if (allDates) {
      const dt = DateTime.fromISO(String(v));
      return dt.isValid ? dt.toMillis() : NaN;
    }
    // numeric mode
    const n = typeof v === "number" ? v : Number(String(v));
    return Number.isFinite(n) ? n : NaN;
  };

  // Find interval index for a comparable numeric value x
  // returns:
  //  - -1  for < bounds[0]
  //  - i   for bounds[i] <= x < bounds[i+1]  (0 <= i < bounds.length-1)
  //  - bounds.length-1 for >= bounds[last]
  const findIntervalIndex = (x) => {
    if (!Number.isFinite(x)) return null; // invalid -> null label
    if (x < bounds[0]) return -1;
    for (let i = 0; i < bounds.length - 1; i++) {
      const left = bounds[i];
      const right = bounds[i + 1];
      const leftOk = x >= left;
      const rightOk = includeUpper ? x <= right : x < right;
      if (leftOk && rightOk) return i;
    }
    // if not found in middle intervals, it's >= last bound
    return bounds.length - 1;
  };

  // Build result
  const result = df.map((row) => {
    const raw = row[colName];
    const parsed = parseValue(raw);
    const idx = findIntervalIndex(parsed);
    const label =
      idx === null
        ? null
        : idx === -1
        ? under
        : idx === bounds.length - 1
        ? over
        : intervalLabels[idx];
    // copy row and attach label
    return { ...row, [outputCol]: label };
  });

  return result;
}

