import { Temporal } from '@js-temporal/polyfill';

/**
 * Convert the "Date" column values in df0 to native JS Date objects by parsing "DD-MM-YYYY".
 *
 * @param {Array<Object>} df0 - array of row objects (tabular dataset)
 * @param {Object} [opts]
 *   - columnName {string} name of the date column (default: 'Date')
 *   - inPlace {boolean} modify df0 in-place (default: false; returns a shallow-copied array)
 *   - onError {'null'|'leave'|'throw'} how to handle parse errors (default: 'null')
 * @returns {Array<Object>} new array (or same array if inPlace=true) with Date column converted to JS Date or handled per onError
 */
export function convertDateColumn(df0, opts = {}) {
  if (!Array.isArray(df0)) throw new TypeError('df0 must be an array of row objects');

  const {
    columnName = 'Date',
    inPlace = false,
    onError = 'null', // options: 'null', 'leave', 'throw'
  } = opts;

  const rows = inPlace ? df0 : df0.map(row => ({ ...row }));

  const ddmmyyyyRegex = /^(\d{1,2})-(\d{1,2})-(\d{4})$/;

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const raw = row[columnName];

    // Already a native Date — leave as-is
    if (raw instanceof Date) continue;

    // Null/undefined/empty string -> set to null (or handle per onError)
    if (raw == null || raw === '') {
      row[columnName] = null;
      continue;
    }

    const s = String(raw).trim();
    const m = s.match(ddmmyyyyRegex);
    if (!m) {
      if (onError === 'throw') throw new Error(`Row ${i}: Date value "${raw}" does not match DD-MM-YYYY`);
      if (onError === 'leave') continue;
      row[columnName] = null;
      continue;
    }

    const day = Number(m[1]);
    const month = Number(m[2]);
    const year = Number(m[3]);

    try {
      // Use Temporal.PlainDate to validate the components (will throw for invalid dates)
      Temporal.PlainDate.from({ year, month, day });

      // Convert to native JS Date (local midnight). If you prefer UTC midnight, use Date.UTC(...)
      row[columnName] = new Date(year, month - 1, day);
    } catch (err) {
      if (onError === 'throw') throw err;
      if (onError === 'leave') continue;
      row[columnName] = null;
    }
  }

  return rows;
}
