      const iso = parseISO(s);
      if (isValid(iso)) return iso;
    } catch (e) { /* ignore */ }

    // Try provided date formats
    for (const fmt of dateFormats) {
      try {
        const d = parse(s, fmt, new Date());
        if (isValid(d)) return d;
      } catch (e) { /* ignore */ }
    }

    return null;
