 *     - an array of objects (rows) or an object-of-arrays (columns) that polars can convert.
 * - lst0 is an array of integer row indices (0-based). Indices must be in range [0, df0.height-1].
 *
 * Returns a new polars DataFrame with rows reordered.
 *
 * Throws RangeError on out-of-bounds indices.
 */
function reorderRows(df0, lst0) {
  if (!Array.isArray(lst0)) throw new TypeError('lst0 must be an array of indices');

  // Convert input to a polars DataFrame if it's not already one
  const df = (df0 && typeof df0 === 'object' && df0 instanceof pl.DataFrame)
    ? df0
    : pl.DataFrame(df0); // pl.DataFrame(...) accepts array-of-objects or object-of-arrays

  const n = df.height;

  // Normalize and validate indices
  const indices = lst0.map((v, i) => {
    const idx = Number(v);
    if (!Number.isInteger(idx)) throw new TypeError(`lst0[${i}] is not an integer: ${v}`);
    if (idx < 0 || idx >= n) throw new RangeError(`Index out of bounds: ${idx} (valid 0..${n - 1})`);
    return idx;
  });

  // Use polars' take to select rows by index order
  // DataFrame.take accepts an array of integer indices
  return df.take(indices);
