// Importing required functions from ramda
const R = require('ramda');

/**
 * Computes the number of distinct characters in a string that occur more than once.
 * @param {string} var0 - The input string to analyze.
 * @returns {number} - The count of distinct characters that appear more than once.
 */
function countDistinctRepeatingCharacters(var0) {
  // Split the string into an array of characters
  const chars = R.split('', var0);

  // Count the occurrences of each character
  const charCounts = R.pipe(
    R.groupBy(R.identity),
    R.mapObjIndexed((value, key) => value.length)
  )(chars);

  // Filter characters that occur more than once and get their count
  const repeatingCharsCount = R.pipe(
    R.toPairs,
    R.filter(pair => pair[1] > 1),
    R.length
  )(charCounts);

  return repeatingCharsCount;
}

