import * as aq from "arquero";

/**
 * Keep only groups (by groupCol) that have more than one row, and reset row indices to a continuous sequence.
 *
 * @param {Array<Object>|aq.Table} data - Input tabular data, either an array of objects or an Arquero table.
 * @param {string} groupCol - Column name used to define groups.
 * @param {Object} [opts] - Options.
 * @param {number} [opts.startIndex=0] - Starting value for the new row index (0 or 1 commonly).
 * @param {string} [opts.indexName='_rowIndex'] - Name of the new index column to add.
 * @param {'array'|'table'} [opts.returnType='array'] - Return either plain array of objects ('array') or an Arquero table ('table').
 * @returns {Array<Object>|aq.Table} Resulting dataset filtered to groups with >1 rows and with a continuous index column.
 *
 * Example:
 *   const data = [
 *     {id: 1, group: 'A', value: 10},
 *     {id: 2, group: 'A', value: 20},
 *     {id: 3, group: 'B', value: 5},
 *   ];
 *   const res = filterGroupsWithDuplicates(data, 'group');
 */
export function filterGroupsWithDuplicates(data, groupCol, opts = {}) {
  const {
    startIndex = 0,
    indexName = "_rowIndex",
    returnType = "array",
  } = opts;

  // Ensure we have an Arquero table
  const tbl = aq.table ? aq.from(data) : aq.from(data); // defensive; always use aq.from

  // Validate group column exists
  const cols = tbl.columnNames();
  if (!cols.includes(groupCol)) {
    throw new Error(`Group column "${groupCol}" not found in data (available columns: ${cols.join(", ")})`);
  }

  // Filter: keep only groups whose group-table has more than 1 row
  const filteredTbl = tbl.groupby(groupCol).filter(g => g.numRows() > 1);

  // Convert to plain objects, reset index, and either return array or new Arquero table
  const rows = filteredTbl.objects();
  const reindexed = rows.map((row, i) => {
    // Avoid clobbering existing property with same indexName; overwrite intentionally
    return { ...row, [indexName]: startIndex + i };
  });

  if (returnType === "table") {
    return aq.from(reindexed);
  } else {
    return reindexed;
  }
}

