 * @param {Array<string>} keyColumns - Column names to group by
 * @returns {Object} Object with group combinations as keys and counts as values
 */
async function countGroupCombinations(df, keyColumns) {
  // Validate inputs
  if (!df || !keyColumns || keyColumns.length === 0) {
    throw new Error("DataFrame and keyColumns array are required");
  }

  // Group by the specified columns and count
