  // Convert to a readable format
  const result = {};

  grouped.values.forEach((row, index) => {
    // Create a key from the combination of values
    const keyValues = keyColumns.map((col, i) => `${col}:${row[i]}`).join("|");
    // Get the count (last column typically contains the count)
    const count = row[row.length - 1];
    result[keyValues] = count;
  });

  return result;
}

