 * Filter a tabular dataset by matching field values against a collection
 * @param {dfd.DataFrame} df0 - The input dataset
 * @param {string} var0 - The column name to filter on
 * @param {Array} lst0 - Collection of values to match
 * @returns {dfd.DataFrame} - Filtered dataset containing only matching rows
 */
function filterDatasetByValues(df0, var0, lst0) {
  // Create a boolean mask where var0 matches any value in lst0
  const mask = df0[var0].apply((val) => lst0.includes(val));

