# Cell Update Function Using Danfo.js (2023+)

```javascript
import * as dfd from "danfo-js-node"; // Version 1.1.2+ (2023)

/**
 * Updates specific cells in df0 based on corresponding cells in df1
 * @param {dfd.DataFrame} df0 - The target dataframe to be modified
 * @param {dfd.DataFrame} df1 - The source dataframe with update values
 * @param {string[]} columns - Column names to update (must exist in both dataframes)
 * @param {string} [matchColumn] - Optional: column to match rows by (default: uses index)
 * @returns {dfd.DataFrame} - Updated dataframe
 */
function updateDataframeFromAnother(df0, df1, columns, matchColumn = null) {
  // Create a copy to avoid mutating original
  let updatedDf = df0.copy();

  // Validate columns exist in both dataframes
  const df0Cols = updatedDf.columns;
  const df1Cols = df1.columns;

  columns.forEach((col) => {
    if (!df0Cols.includes(col) || !df1Cols.includes(col)) {
      throw new Error(
        `Column '${col}' not found in both dataframes. df0 cols: ${df0Cols}, df1 cols: ${df1Cols}`
      );
    }
  });

  // Update based on matching column or index
  if (matchColumn) {
    if (!df0Cols.includes(matchColumn) || !df1Cols.includes(matchColumn)) {
      throw new Error(`Match column '${matchColumn}' not found in both dataframes`);
    }

    const df0MatchValues = updatedDf[matchColumn].values;
    const df1MatchValues = df1[matchColumn].values;

    df0MatchValues.forEach((value, idx0) => {
      const idx1 = df1MatchValues.indexOf(value);
      if (idx1 !== -1) {
        columns.forEach((col) => {
          updatedDf.loc({ rows: [idx0], columns: [col] }, df1.loc({ rows: [idx1], columns: [col] }));
        });
      }
    });
  } else {
    // Match by index position
    const df0Size = updatedDf.shape[0];
    const df1Size = df1.shape[0];
    const matchSize = Math.min(df0Size, df1Size);

    for (let i = 0; i < matchSize; i++) {
      columns.forEach((col) => {
        const newValue = df1.loc({ rows: [i], columns: [col] }).values[0];
        updatedDf.loc({ rows: [i], columns: [col] }, newValue);
      });
    }
  }

  return updatedDf;
}

// ============== EXAMPLE USAGE ==============

async function main() {
  // Create sample dataframes
  const df0 = new dfd.DataFrame({
    id: [1, 2, 3, 4],
    name: ["Alice", "Bob", "Charlie", "David"],
    score: [85, 90, 78, 92],
    status: ["active", "active", "inactive", "active"],
  });

  const df1 = new dfd.DataFrame({
    id: [1, 2, 3, 4],
    score: [88, 95, 82, 96],
    status: ["active", "inactive", "inactive", "pending"],
  });

  console.log("=== Original DataFrame (df0) ===");
  df0.print();

  console.log("\n=== Update Source DataFrame (df1) ===");
  df1.print();

  // Update df0 with values from df1 (by index)
  const updated = updateDataframeFromAnother(
    df0,
    df1,
    ["score", "status"]
  );

  console.log("\n=== Updated DataFrame ===");
  updated.print();

  // Example with matching column
  const df2 = new dfd.DataFrame({
    id: [2, 3],
    score: [99, 100],
  });

  console.log("\n=== Selective Update by ID ===");
  const updated2 = updateDataframeFromAnother(
    df0,
    df2,
    ["score"],
    "id"
  );
  updated2.print();
}

main().catch(console.error);
```

