import * as dfd from "danfo-js-node";

/**
 * Adds group statistics columns to a dataset
 * @param {dfd.DataFrame} df0 - Input dataframe with var0 (grouping variable) and var1 (numeric variable)
 * @returns {dfd.DataFrame} Updated dataframe with var1_mean and var1_sum columns
 */
function addGroupStatistics(df0) {
  // Create a copy to avoid mutating the original
  let result = df0.copy();

  // Group by var0 and calculate mean and sum of var1
  const groupedMean = df0.groupby(["var0"]).agg({ var1: "mean" });
  const groupedSum = df0.groupby(["var0"]).agg({ var1: "sum" });

  // Rename columns for clarity
  groupedMean.rename({ var1: "var1_mean" }, { inplace: true });
  groupedSum.rename({ var1: "var1_sum" }, { inplace: true });

  // Reset index to make var0 a regular column for merging
  const meanWithIndex = groupedMean.reset_index();
  const sumWithIndex = groupedSum.reset_index();

  // Merge the statistics back to the original dataframe
  result = result.merge({
    right: meanWithIndex,
    on: ["var0"],
    how: "left"
  });

  result = result.merge({
    right: sumWithIndex,
    on: ["var0"],
    how: "left"
  });

  return result;
}

