 * @param {dfd.DataFrame} df0 - First DataFrame
 * @param {dfd.DataFrame} df1 - Second DataFrame (must be same shape as df0)
 * @returns {dfd.DataFrame} DataFrame containing df0 - df1
 */
function computeDataFrameDifference(df0, df1) {
  // Verify that both DataFrames have the same shape
  if (
