function createHierarchicalIndex(df0, str0, str1) {
  /**
   * Changes the row index of a Danfo.js DataFrame to a two-level hierarchical index
   * using values from two specified columns.
   * 
   * @param {dfd.DataFrame} df0 - The input DataFrame
   * @param {string} str0 - Name of the first column for the first level of the index
   * @param {string} str1 - Name of the second column for the second level of the index
   * @returns {dfd.DataFrame} - DataFrame with new hierarchical index
   */

  // Extract the two columns as arrays
  const level0 = df0[str0].values;
  const level1 = df0[str1].values;

  // Create a multi-level index by combining the two columns
  const multiIndex = level0.map((val0, idx) => 
    `${val0}|${level1[idx]}`
  );

  // Create a new DataFrame with the original data
  let resultDf = df0.copy();

  // Set the new multi-level index
  resultDf.setIndex({
    "key": multiIndex,
    "inplace": true
  });

  // Rename the index to reflect the hierarchical structure
  resultDf.index.name = [str0, str1];

  return resultDf;
}

