/**
 * Filter table using Danfo.js DataFrame
 * @param {Array<Array>} data - 2D array with headers as first row
 * @param {Object} filterConfig - Object with column names as keys, values as filter criteria
 * @returns {Array<Array>} - Filtered 2D array
 */
function filterTableWithDanfo(data, filterConfig) {
  const headers = data[0];
  const dataRows = data.slice(1);

  // Create DataFrame
  const df = new dfd.DataFrame(dataRows, { columns: headers });

  // Apply filters
  let filtered = df;
  for (const [column, value] of Object.entries(filterConfig)) {
    if (Array.isArray(value)) {
      // Range filter [min, max]
      filtered = filtered.loc({ rows: filtered[column].ge(value[0]).and(filtered[column].le(value[1])) });
    } else {
      // Exact match filter
      filtered = filtered.loc({ rows: filtered[column].eq(value) });
    }
  }

  // Convert back to 2D array
  const result = [headers];
  for (let i = 0; i < filtered.values.length; i++) {
    result.push(filtered.values[i]);
  }
  return result;
}

