  { Age: 25, Age: 28, Salary: 50000, Salary: 55000 },
  { Age: 30, Age: 32, Salary: 60000, Salary: 65000 },
  { Age: 35, Age: 40, Salary: 75000, Salary: 80000 },
];

const result = calculateMeanByDuplicateNames(rawData);
