# Filter DataFrame Rows by Sum Using Danfo.js

```javascript
const dfd = require("danfo-js-node");

function filterNonZeroSumRows(df0) {
  /**
   * Filters and returns only rows from a 2D table where the sum of elements
   * in each row is non-zero.
   *
   * @param {DataFrame} df0 - A Danfo.js DataFrame
   * @returns {DataFrame} - Filtered DataFrame with only non-zero sum rows
   */

  // Calculate the sum of each row
  const rowSums = df0.values.map((row) =>
    row.reduce((sum, val) => sum + (Number(val) || 0), 0)
  );

  // Get indices of rows with non-zero sums
  const nonZeroIndices = rowSums
    .map((sum, index) => (sum !== 0 ? index : -1))
    .filter((index) => index !== -1);

  // Filter the DataFrame to keep only non-zero sum rows
  const filteredDf = df0.iloc({ rows: nonZeroIndices });

  return filteredDf;
}

// Example usage:
