 * @param {dfd.DataFrame} df0 - Input 2D DataFrame
 * @param {number} var0 - Axis along which to iterate (0 for rows, 1 for columns)
 * @param {Function} func - Function to apply to each element
 * @returns {dfd.DataFrame} - New DataFrame with transformed values
 */
function iterateAndApply(df0, var0, func) {
  if (!(df0 instanceof dfd.DataFrame)) {
    throw new Error("Input must be a Danfo DataFrame");
  }

  if (var0 === 0) {
    // Iterate along rows (axis 0)
    return df0.applyMap((value) => func(value));
  } else if (var0 === 1) {
    // Iterate along columns (axis 1)
    const result = {};
    df0.columns.forEach((col) => {
      result[col] = df0[col].map((value) => func(value));
    });
    return new dfd.DataFrame(result);
  } else {
    throw new Error("var0 must be 0 (rows) or 1 (columns)");
  }
}

