/**
 * Compute the mean of corresponding entries across multiple 2D numeric tables
 * @param {number[][][]} lst0 - List of 2D numeric arrays
 * @returns {number[][]} - 2D array containing means of corresponding entries
 */
function meanOfCorrespondingEntries(lst0) {
  if (!lst0 || lst0.length === 0) {
    throw new Error("Input list cannot be empty");
  }

  const numTables = lst0.length;
  const rows = lst0[0].length;
  const cols = lst0[0][0].length;

  // Validate all tables have same dimensions
  for (let table of lst0) {
    if (table.length !== rows || table[0].length !== cols) {
      throw new Error("All tables must have the same dimensions");
    }
  }

  // Create result array initialized with zeros
  const result = Array.from({ length: rows }, () => Array(cols).fill(0));

  // Sum all corresponding entries
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      let sum = 0;
      for (let t = 0; t < numTables; t++) {
        sum += lst0[t][i][j];
      }
      result[i][j] = sum / numTables;
    }
  }

  return result;
