# Replace Missing Values in Categorical Columns with Mode

```javascript
import * as dfd from "danfo-js-node"; // v1.1.2+ (2023)

/**
 * Replace missing entries in categorical columns with the most frequently 
 * occurring category (mode) in each column.
 * 
 * @param {dfd.DataFrame} df - Input DataFrame with potential missing values
 * @returns {dfd.DataFrame} DataFrame with missing categorical values filled with mode
 */
function fillCategoricalWithMode(df) {
  // Create a copy to avoid modifying the original
  const df0 = df.copy();

  // Iterate through each column
  df0.columns.forEach((colName) => {
    const column = df0[colName];

    // Check if column has missing values
    const hasNull = column.values.some(val => val === null || val === undefined || Number.isNaN(val));

    if (hasNull) {
      // Get non-null values
      const nonNullValues = column.values.filter(
        val => val !== null && val !== undefined && !Number.isNaN(val)
      );

      if (nonNullValues.length > 0) {
        // Find the mode (most frequent value)
        const frequency = {};
        nonNullValues.forEach((val) => {
          frequency[val] = (frequency[val] || 0) + 1;
        });

        const mode = Object.keys(frequency).reduce((a, b) =>
          frequency[a] > frequency[b] ? a : b
        );

        // Fill missing values with mode
        const filledValues = column.values.map(val =>
          val === null || val === undefined || Number.isNaN(val) ? mode : val
        );

        df0[colName] = filledValues;
      }
    }
  });

  return df0;
}

// Example usage:
const data = {
  color: ["red", "blue", null, "red", "green", null, "blue"],
  size: ["S", "M", "L", null, "M", "S", null],
  price: [10, 20, 15, null, 25, 10, 20]
};

