 * @param {Object} df0 - Input dataframe/dataset
 * @param {string} var0 - Field name to group by
 * @param {Function} agg_function - Aggregation function (e.g., 'mean', 'sum', 'count')
 * @returns {Array<Array>} 2D array representing the aggregated table
 */
function groupAndAggregate(df0, var0, agg_function) {
  // Install danfo-js: npm install danfo-js-node
  const dfd = require('danfo-js-node');

  // Convert input to Danfo DataFrame if not already
  let df = df0 instanceof dfd.DataFrame ? df0 : new dfd.DataFrame(df0);

  // Group by var0 and apply aggregation function
  const grouped = df.groupby([var0]).agg({
    // Apply agg_function to all numeric columns except the grouping column
    ...Object.fromEntries(
      df.columns
        .filter(col => col !== var0 && df[col].dtype !== 'string')
        .map(col => [col, agg_function])
    )
  });

  // Convert to 2D array format
  const result = [
    // Header row
    [var0, ...grouped.columns.filter(col => col !== var0)],
    // Data rows
    ...grouped.values.map(row => row)
  ];

  return result;
}

