async function computeAverageIndices(df0) {
  /**
   * Computes average row and column indices of nonzero entries in a 2D table
   * @param {danfo.DataFrame} df0 - Input dataframe
   * @returns {Object} Object with avgRowIndex and avgColIndex properties
   */

  let rowIndexSum = 0;
  let colIndexSum = 0;
  let nonzeroCount = 0;

  // Get dimensions
  const numRows = df0.shape[0];
  const numCols = df0.shape[1];
  const colNames = df0.columns;

  // Iterate through all entries
  for (let i = 0; i < numRows; i++) {
    for (let j = 0; j < numCols; j++) {
      const value = df0.iloc({ rows: [i], columns: [colNames[j]] }).values[0][0];

      // Check if nonzero
      if (value !== 0 && value !== null && value !== undefined && !Number.isNaN(value)) {
        rowIndexSum += i;
        colIndexSum += j;
        nonzeroCount++;
      }
    }
  }

  // Calculate averages
  const avgRowIndex = nonzeroCount > 0 ? rowIndexSum / nonzeroCount : null;
  const avgColIndex = nonzeroCount > 0 ? colIndexSum / nonzeroCount : null;

  return {
    avgRowIndex,
    avgColIndex,
    nonzeroCount
  };
}

