  /**
   * Normalize a 2D table (array of objects) to [0, 1] range
   * @param {Array<Object>} df0 - Input table as array of objects
   * @returns {Array<Object>} - Normalized table
   */

  if (!df0 || df0.length === 0) return df0;

  const columns = Object.keys(df0[0]);

  // Calculate min and max for each column
  const stats = {};
  for (const col of columns) {
    const values = df0.map(row => row[col]);
    stats[col] = {
      min: Math.min(...values),
      max: Math.max(...values)
    };
  }

  // Apply min-max normalization
  return df0.map(row => {
    const normalizedRow = {};
    for (const col of columns) {
      const { min, max } = stats[col];
      const range = max - min;
      normalizedRow[col] = range === 0 ? 0 : (row[col] - min) / range;
    }
    return normalizedRow;
  });
}

// Example usage:
