// For browser: <script src="https://cdn.jsdelivr.net/npm/danfo-js@1.1.2/dist/index.min.js"></script>

const dfd = require('danfo-js-node');

function convertListsTo2DTable(dataLists, columnHeaders) {
  /**
   * Converts multiple lists into a 2D table with specified column headers
   * @param {Array<Array>} dataLists - List containing multiple lists (rows)
   * @param {Array<string>} columnHeaders - List of column header names
   * @returns {Object} Danfo DataFrame (2D table)
   */

  // Validate inputs
  if (!Array.isArray(dataLists) || !Array.isArray(columnHeaders)) {
    throw new Error('Both parameters must be arrays');
  }

  if (dataLists.length === 0) {
    throw new Error('dataLists cannot be empty');
  }

  // Check that all rows have same length as headers
  const headerCount = columnHeaders.length;
  const validData = dataLists.every(row => 
    Array.isArray(row) && row.length === headerCount
  );

  if (!validData) {
    throw new Error(
      `All rows must have ${headerCount} elements matching column header count`
    );
  }

  // Create DataFrame from data
  const dataObject = {};
  columnHeaders.forEach((header, index) => {
    dataObject[header] = dataLists.map(row => row[index]);
  });

  const df = new dfd.DataFrame(dataObject);

  return df;
}

// Example Usage:
const lists = [
  [1, 'Alice', 95],
  [2, 'Bob', 87],
  [3, 'Charlie', 92],
  [4, 'Diana', 88]
];

