 * Uses Polars.js for efficient data manipulation.
 * 
 * @param {Array<Array>} data - 2D array representing the table
 * @param {Array<string>} labels - Column labels
 * @returns {Object} Grouped sums with labels as keys
 */
function groupAndSumColumnsPolars(data, labels) {
  const pl = require('polars');

  // Create a DataFrame with labeled columns
  const df = pl.DataFrame(
    Object.fromEntries(
      labels.map((label, idx) => [
        `${label}_${idx}`,
        data.map(row => row[idx])
      ])
    )
  );

  // Group and sum by label
  const groupedSums = {};
  const uniqueLabels = [...new Set(labels)];

  for (const label of uniqueLabels) {
    const relevantCols = labels
      .map((l, i) => l === label ? `${label}_${i}` : null)
      .filter(col => col !== null);

    // Sum across relevant columns
    const sums = df
      .select([...relevantCols])
      .select(
        pl.col('*').sum().alias(`${label}_sum`)
      )
      .getColumn(`${label}_sum`)
      .toArray();

    groupedSums[label] = sums.length === 1 ? sums[0] : sums;
  }

  return groupedSums;
}
```

