  /**
   * Replaces missing entries with column averages (pure JS, no dependencies)
   * @param {number[][]} data - 2D array with potential missing values
   * @returns {number[][]} - 2D array with missing values filled
   */

  if (!data || data.length === 0) return data;

  const numCols = data[0].length;
  const result = data.map(row => [...row]);

  // Calculate column averages (ignoring missing values)
  const columnAverages = Array(numCols).fill(0).map((_, colIndex) => {
    const values = result
      .map(row => row[colIndex])
      .filter(val => val != null && !Number.isNaN(val));

    return values.length > 0 
      ? values.reduce((a, b) => a + b, 0) / values.length 
      : 0;
  });

