  for (let i = 0; i < result.length; i++) {
    for (let j = 0; j < numCols; j++) {
      if (result[i][j] == null || Number.isNaN(result[i][j])) {
        result[i][j] = columnAverages[j];
      }
    }
  }

  return result;
}

