# Column-Ordered Table Concatenation

```javascript
import Danfo from "danfo-js-node"; // npm install danfo-js-node (2023+)

/**
 * Concatenates new columns onto a base table while preserving a specified column order.
 * 
 * @param {Danfo.DataFrame} baseTable - The base DataFrame
 * @param {Danfo.DataFrame} newColumns - DataFrame containing new columns to concatenate
 * @param {string[]} priorityOrder - Column names in desired priority order
 * @returns {Danfo.DataFrame} Merged table with columns in specified order
 */
function concatenateWithColumnOrder(baseTable, newColumns, priorityOrder) {
  // Concatenate horizontally (axis=1)
  const merged = baseTable.concat(newColumns, { axis: 1 });

  // Get all column names
  const allColumns = merged.columns;

  // Separate priority columns from others
  const priorityColumnsPresent = priorityOrder.filter(col => 
    allColumns.includes(col)
  );

  const otherColumns = allColumns.filter(col => 
    !priorityOrder.includes(col)
  );

  // Combine: priority columns first, then others in original order
  const finalColumnOrder = [...priorityColumnsPresent, ...otherColumns];

  // Select columns in the desired order
  return merged.loc({ columns: finalColumnOrder });
}

// Example usage:
const baseTable = new Danfo.DataFrame({
  A: [1, 2, 3],
  B: [4, 5, 6],
  C: [7, 8, 9]
});

const newColumns = new Danfo.DataFrame({
  D: [10, 11, 12],
  E: [13, 14, 15]
});

const priorityOrder = ["E", "A", "D"];

const result = concatenateWithColumnOrder(baseTable, newColumns, priorityOrder);
console.log(result.toString());
