```javascript
const dfd = require("danfo-js-node"); // Danfo.js 1.1.2+ (2023+)

/**
 * Count the number of distinct entries in column var1 
 * for each unique value in column var0 of the table df0
 * 
 * @param {Object} df0 - A Danfo.js DataFrame
 * @returns {Object} Object with var0 values as keys and distinct counts as values
 */
function countDistinctByGroup(df0) {
  // Group by var0 and apply a function to count distinct values in var1
  const result = {};

  const groupedData = df0.groupby(["var0"]);
  const groups = groupedData.groups;

  for (const [groupKey, indices] of Object.entries(groups)) {
    // Get the var1 values for this group
    const var1Values = df0.loc({ rows: indices })["var1"].values;

    // Count distinct values using a Set
    const distinctCount = new Set(var1Values).size;

    result[groupKey] = distinctCount;
  }

  return result;
}

