function addSplitColumn(df0, sourceColumn, newColumn, splitIndex = 0, delimiter = " ") {
  /**
   * Adds a new column to a dataframe by splitting values from an existing column
   * 
   * @param {dfd.DataFrame} df0 - The input dataframe
   * @param {string} sourceColumn - Name of the column to split (e.g., 'var0')
