 * Convert a tabular dataset into a list of dictionaries
 * Each dictionary represents one row with column names as keys
 * @param {DataFrame} df - Danfo.js DataFrame
 * @returns {Array<Object>} Array of dictionaries
 */
function dataframeToListOfDicts(df) {
  const columnNames = df.columns;
