```javascript
import * as dfd from "danfo-js-node"; // Danfo.js 1.1.2+

async function removeDuplicatesKeepMaxC(df0) {
  /**
   * Eliminates duplicates based on fields A and B,
   * keeping only the entry with the maximum C value
   * for each unique combination of A and B.
   * 
   * @param {dfd.DataFrame} df0 - Input dataframe with columns A, B, and C
   * @returns {dfd.DataFrame} - Deduplicated dataframe
   */

  // Add an index for tracking original row positions
  const dfWithIndex = df0.copy();
  dfWithIndex.addColumn('__index__', [...Array(dfWithIndex.shape[0]).keys()]);

  // Sort by A, B (ascending) and C (descending) to prepare for deduplication
  const sorted = dfWithIndex.sort_values({
    by: ['A', 'B', 'C'],
    ascending: [true, true, false]
  });

  // Drop duplicates based on A and B columns, keeping first occurrence
  // (which has the maximum C value due to our sorting)
  const result = sorted.drop_duplicates({
    subset: ['A', 'B'],
    keep: 'first'
  });

  // Remove the temporary index column and restore original order if needed
  const final = result.drop('__index__', { axis: 1 });

  return final;
}

