```javascript
const dfd = require("danfo-js-node"); // or use in browser: import * as dfd from "danfo-js"

/**
 * Filters a tabular dataset based on a column and list of values
 * @param {dfd.DataFrame} df0 - The input DataFrame
 * @param {string} var0 - The column name to filter on
 * @param {Array} lst0 - List of values to match
 * @param {string} op0 - Operation: "include" to keep rows with matching values, 
 *                       "exclude" to remove rows with matching values
 * @returns {dfd.DataFrame} - The filtered DataFrame
 */
function filterDataset(df0, var0, lst0, op0) {
  // Validate inputs
  if (!df0 || !(df0 instanceof dfd.DataFrame)) {
    throw new Error("df0 must be a valid Danfo DataFrame");
  }

  if (!df0.columns.includes(var0)) {
    throw new Error(`Column "${var0}" not found in DataFrame`);
  }

  if (!Array.isArray(lst0)) {
    throw new Error("lst0 must be an array");
  }

  if (!["include", "exclude"].includes(op0)) {
    throw new Error('op0 must be either "include" or "exclude"');
  }

  // Get the column as a Series
  const column = df0[var0];

  // Create a boolean mask based on operation
  let mask;

  if (op0 === "include") {
    // Keep rows where column value is IN lst0
    mask = column.apply((val) => lst0.includes(val));
  } else {
    // Keep rows where column value is NOT IN lst0
    mask = column.apply((val) => !lst0.includes(val));
  }

  // Filter DataFrame using the mask
  const filteredDf = df0.loc({ rows: mask });

  return filteredDf;
}

