```javascript
/**
 * Encodes categorical values in a DataFrame column to integer codes
 * @param {Object} df - Danfo.js DataFrame
 * @param {string} col - Column name to encode (default: 'col0')
 * @returns {Object} DataFrame with encoded column
 */
function encodeCategoricalColumn(df, col = 'col0') {
  // Get unique values from the column
  const uniqueValues = [...new Set(df[col].values)];

  // Create mapping object: category -> integer code
  const categoryMap = {};
  uniqueValues.forEach((category, index) => {
    categoryMap[category] = index;
  });

  // Replace column values with their corresponding codes
  const encodedValues = df[col].values.map(value => categoryMap[value]);

  // Create new DataFrame with encoded column
  const dfEncoded = df.copy();
  dfEncoded[col] = encodedValues;

  return { dataframe: dfEncoded, mapping: categoryMap };
}

