 * @param {Array<boolean>} descending - Sort direction (default: all ascending)
 * @returns {Array<Array>} Sorted 2D array
 */
function sortDataFramePolars(data, columns, descending = null) {
  const [headers, ...rows] = data;

  // Convert to Polars DataFrame
  const df = pl.DataFrame(
    Object.fromEntries(
      headers.map((col, i) => [col, rows.map(row => row[i])])
    )
  );

  // Set default descending values
  if (!descending) {
    descending = columns.map(() => false);
  }

  // Sort and convert back to 2D array
  const sorted = df.sort(columns, descending);
  const result = [headers, ...sorted.toRecords().map(row => headers.map(h => row[h]))];

  return result;
}

// Example usage:
