# Z-Score Normalization Function

Here's a self-contained JavaScript function using **Danfo.js** (a 2023+ pandas-like library for JavaScript):

```javascript
const dfd = require("danfo-js-node");

/**
 * Apply z-score normalization to all columns in a dataframe
 * @param {dfd.DataFrame} df0 - Input dataframe
 * @returns {dfd.DataFrame} - Normalized dataframe with zero mean and unit variance
 */
function zScoreNormalization(df0) {
  // Clone the dataframe to avoid modifying the original
  let normalized = df0.copy();

  // Get all column names
  const columns = normalized.columns;

  // Apply z-score normalization to each column
  columns.forEach(col => {
    const column = normalized[col];
    const mean = column.mean();
    const std = column.std();

    // Z-score formula: (x - mean) / std
    normalized[col] = column.sub(mean).div(std);
  });

  return normalized;
}

// Example usage:
const data = {
  feature1: [10, 20, 30, 40, 50],
  feature2: [100, 200, 300, 400, 500],
  feature3: [1, 2, 3, 4, 5]
};

const df0 = new dfd.DataFrame(data);

console.log("Original DataFrame:");
df0.print();

const normalized = zScoreNormalization(df0);

console.log("\nNormalized DataFrame (z-score):");
normalized.print();

// Verify: check means (should be ~0) and std (should be ~1)
console.log("\nMeans:", normalized.mean().values);
console.log("Std Devs:", normalized.std().values);
```

