/**
 * Merges two DataFrames by matching on a shared key column
 * @param {Object} df0 - First DataFrame
 * @param {Object} df1 - Second DataFrame
 * @param {Array<string>} lst0 - List of column names from df0 to include
 * @param {string} var0 - Shared key column name for matching
 * @returns {Object} Merged DataFrame
 */
function mergeDataFrames(df0, df1, lst0, var0) {
  const dfd = require('danfo-js-node'); // or use in browser: window.dfd

  // Select only the specified columns from df0, plus the key column
  const columnsToSelect = [...new Set([var0, ...lst0])]; // Remove duplicates
  const df0_subset = df0.loc({ columns: columnsToSelect });

  // Merge df0_subset with df1 on the shared key
  const merged = dfd.merge({
    left: df0_subset,
    right: df1,
    on: var0,
    how: 'inner' // Use 'left', 'right', 'outer' as needed
  });

  return merged;
}

// Example Usage:
if (typeof require !== 'undefined') {
  const dfd = require('danfo-js-node');

  // Create sample DataFrames
