 * Divides specified columns in a dataframe by a reference column
 * @param {Object} df0 - Danfo.js DataFrame
 * @param {Array<string>} columns_list0 - List of column names to divide
 * @param {string} column_name0 - Reference column name to divide by
 * @returns {Object} - New DataFrame with divided values
 */
function divideColumnsByReference(df0, columns_list0, column_name0) {
  // Validate inputs
  if (!df0 || typeof df0 !== 'object') {
    throw new Error('Invalid DataFrame provided');
  }

  if (!Array.isArray(columns_list0) || columns_list0.length === 0) {
    throw new Error('columns_list0 must be a non-empty array');
  }

  if (typeof column_name0 !== 'string') {
    throw new Error('column_name0 must be a string');
  }

  // Check if reference column exists
  if (!df0.columns.includes(column_name0)) {
    throw new Error(`Reference column "${column_name0}" not found in DataFrame`);
  }

  // Create a copy to avoid modifying original
  let result = df0.copy();

  // Get the reference column values
  const refColumn = df0[column_name0];

  // Divide each specified column by the reference column
  columns_list0.forEach(col => {
    if (!df0.columns.includes(col)) {
      console.warn(`Column "${col}" not found, skipping...`);
      return;
    }

    // Perform element-wise division
    result[col] = df0[col].div(refColumn);
  });

  return result;
}

